/* DAWAH X — ahmad, অধ্যায় 45 · খণ্ড 45 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][45]=[[8801,8801,"","আর এই আহ্বানের নাম হচ্ছে নবী তার কাছে এসেছে এবং তিনি প্রভুর কাছে তার প্রভুর কাছে এই কথা পৌঁছে দিয়েছেন, এমনকি শহরের দেওয়ালও ভেঙ্গে পড়েছে এবং তারপর আপনি সামনে এগিয়ে যাচ্ছেন। আর বলে যে বাবা এখানে আছে।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَأْتِي ‏ ‏الْمَسِيحُ الدَّجَّالُ ‏ ‏مِنْ قِبَلِ الْمَشْرِقِ وَهِمَّتُهُ ‏ ‏الْمَدِينَةُ ‏ ‏حَتَّى يَنْزِلَ دَائِرَ ‏ ‏أُحُدٍ ‏ ‏ثُمَّ تَصْرِفُ الْمَلَائِكَةُ وَجْهَهُ قِبَلَ ‏ ‏الشَّامِ ‏ ‏وَهُنَالِكَ يَهْلِكُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏كَذَا قَالَ أَبِي فِي هَذِهِ الْأَحَادِيثِ ‏","","",""],[8802,8802,"","আমরা দুটো বিষয় নিয়ে কথা বলেছি যেগুলো আমাদের শোনা উচিত একটা কুত্তার বাচ্চা, যার মানে আমার কাছে একটা উপহার, আমার বাবা তার জন্য প্রার্থনা করেছেন এবং তিনি একই সাথে বলেছেন আমি কোন মেয়েকে তার দুর্ভাগ্য থেকে তার মেয়েকে তার কাছে যেতে দিব না। সে বলল আমরা সেই মেয়ে আর ক্যাপ্টেনের রিং।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏ابْنِ دِينَارٍ يَعْنِي عَبْدَ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ مِنْ قَبْلِي كَمَثَلِ رَجُلٍ بَنَى بُنْيَانًا فَأَحْسَنَهُ وَأَجْمَلَهُ إِلَّا مَوْضِعَ ‏ ‏لَبِنَةٍ ‏ ‏مِنْ زَاوِيَةٍ مِنْ زَوَايَاهُ فَجَعَلَ النَّاسُ يَطُوفُونَ بِهِ وَيَعْجَبُونَ لَهُ وَيَقُولُونَ هَلَّا وُضِعَتْ هَذِهِ ‏ ‏اللَّبِنَةُ ‏ ‏قَالَ فَأَنَا تِلْكَ ‏ ‏اللَّبِنَةُ ‏ ‏وَأَنَا خَاتَمُ النَّبِيِّينَ ‏","","",""],[8803,8803,"","আমি আমার বাবার অতিথি, একটা ঘোড়া, যে ঘোড়া আমার ভাববাদী তার কাছে প্রার্থনা করেছে আর সে জিজ্ঞেস করছে আমি কি এর মধ্যে যাব কিনা? এটা শুধু তার ডানা, আরোগ্য আর চিরকালের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏عُتْبَةُ بْنُ مُسْلِمٍ ‏ ‏مَوْلَى ‏ ‏بَنِي تَمِيمٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏مَوْلَى ‏ ‏بَنِي زُرَيْقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَ الذُّبَابُ فِي شَرَابِ أَحَدِكُمْ فَلْيَغْمِسْهُ كُلَّهُ ثُمَّ لِيَطْرَحْهُ فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ شِفَاءً وَفِي الْآخَرِ دَاءً ‏","","",""],[8804,8804,"","তিনি বলেছিলেন, ঈশ্বর তার জন্য প্রার্থনা করেন এবং তাকে আত্মসমর্পণ করতে হবে যদি তিনি আপনার কোন স্বপ্নে গান গাইতেন।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏","","",""],[8805,8805,"","আমরা বলেছিলাম যে, গতবার আমরা আমার ছেলের জন্য যা করেছিলাম, তা জয় করতে গিয়ে আমরা কীভাবে কথা বলেছিলাম । শিকারী আর প্রার্থনা করে শয়তান যেন শুধু ক্ষতিই করে ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعَ الشَّيْطَانُ الْمُنَادِيَ يُنَادِي بِالصَّلَاةِ ‏ ‏وَلَّى ‏ ‏وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ الصَّوْتَ فَإِذَا فَرَغَ رَجَعَ فَوَسْوَسَ فَإِذَا أَخَذَ فِي الْإِقَامَةِ فَعَلَ مِثْلَ ذَلِكَ ‏","","",""],[8806,8806,"","আমরা আমার ভাই একজন উৎপীড়ক সম্পর্কে কথা বলেছিলাম সে বলেছে যে মানুষের খারাপ থেকে সে কিছু জানতে পারবে যা মানুষের মৃত্যুর দিকে পরিচালিত করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَجِدُ مِنْ شِرَارِ النَّاسِ يَوْمَ الْقِيَامَةِ الَّذِي يَأْتِي هَؤُلَاءِ بِحَدِيثِ هَؤُلَاءِ وَهَؤُلَاءِ بِحَدِيثِ هَؤُلَاءِ ‏","","",""],[8807,8807,"","আমি ঈশ্বরের সঙ্গে কথা বলেছিলাম, যে - বিষয়ে আমি সুখী হতে পারতাম । সূর্য কাজ করছে না, এটা তার নিজের বিশ্বাসে রাখার আগে নিরাপদ ছিল না। এবং লর্ড সাহায্য করে যাবেন।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا فَيُؤْمِنَ النَّاسُ أَجْمَعُونَ فَيَوْمَئِذٍ ‏ { ‏لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا ‏} ‏وَلَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا ‏ ‏الْيَهُودَ ‏ ‏فَيَفِرَّ الْيَهُودِيُّ وَرَاءَ الْحَجَرِ فَيَقُولَ الْحَجَرُ يَا عَبْدَ اللَّهِ يَا مُسْلِمُ هَذَا يَهُودِيٌّ وَرَائِي وَلَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا قَوْمًا نِعَالُهُمْ الشَّعَرُ ‏","","",""],[8808,8808,"","আমি যখন ঘরে ঘরে প্রচার করতাম, তখন আমার বাবা আমাকে একটা বাইবেল অধ্যয়ন পরিচালনা করতে বলেছিলেন । আল্লাহ এবং আল্লাহ এটা করা যায়। এটা একটা ন্যায্য মূল্যবোধ যে আমি জানি না। কিন্তু এটা একটা স্বপ্ন, ঈশ্বর এবং মানুষ এবং মানুষ তার কাছ থেকে ঈশ্বরের কাছে গ্রহণ না করার জন্য একত্রিত হয় এবং দোষের জন্য। কখনোই ধরা যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏تَوَلَّى ‏ ‏قَوْمًا بِغَيْرِ إِذْنِ ‏ ‏مَوَالِيهِ ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏عَدْلًا ‏ ‏وَلَا ‏ ‏صَرْفًا ‏ ‏وَالْمَدِينَةُ ‏ ‏حَرَامٌ فَمَنْ ‏ ‏أَحْدَثَ ‏ ‏فِيهَا أَوْ ‏ ‏آوَى ‏ ‏مُحْدِثًا ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏عَدْلًا ‏ ‏وَلَا ‏ ‏صَرْفًا ‏ ‏وَذِمَّةُ ‏ ‏الْمُسْلِمِينَ وَاحِدَةٌ ‏ ‏يَسْعَى بِهَا ‏ ‏أَدْنَاهُمْ ‏ ‏فَمَنْ ‏ ‏أَخْفَرَ ‏ ‏مُسْلِمًا فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏عَدْلًا ‏ ‏وَلَا ‏ ‏صَرْفًا ‏","","",""],[8809,8809,"","আমরা কিভাবে বলছি আমরা শুরু করেছি এবং আমরা যে সময় শুরু করেছি তা পরিবর্তন করেছি। ভবিষ্যদ্বাণীটি তার কাছে প্রার্থনা করেছে এবং ঈশ্বরের শোক ও শোকের জন্য তাকে উদ্ধার করা হবে আমার ভাইয়ের দৃষ্টি ধরে রাখার জন্য, ঈশ্বরের সকল কথায় বিশ্বাস করাই উচিৎ, অথবা তার কাছে ফেরত পাঠানো।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَكَّلَ اللَّهُ عَزَّ وَجَلَّ بِحِفْظِ امْرِئٍ خَرَجَ فِي سَبِيلِ اللَّهِ لَا يُخْرِجُهُ إِلَّا الْجِهَادُ فِي سَبِيلِ اللَّهِ وَتَصْدِيقٌ بِكَلِمَاتِ اللَّهِ حَتَّى يُوجِبَ لَهُ الْجَنَّةَ أَوْ يُرْجِعَهُ إِلَى بَيْتِهِ أَوْ مِنْ حَيْثُ خَرَجَ ‏","","",""],[8810,8810,"","আমি আমার বাবার সাথে মিথ্যা কথা বলেছি, ঈশ্বর তাকে তার হৃদয় ভেঙ্গে ফেলার চেষ্টা করেছেন। তার ফুসফুস আহত হয়েছে, কিন্তু সে রক্ত বহন করে না, এবং সে তার রক্ত বহন করে না। শান্ত হও।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏كُلِمَ ‏ ‏فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِهِ يَجِيءُ يَوْمَ الْقِيَامَةِ جُرْحُهُ كَهَيْئَتِهِ يَوْمَ جُرِحَ لَوْنُهُ لَوْنُ دَمٍ وَرِيحُهُ رِيحُ مِسْكٍ ‏","","",""],[8811,8811,"","আমার বাবা কুমারী হওয়ার কথা বলছিল। আল্লাহ আছে। আমি দুঃখিত যে, তুমি তোমার ভাই আর ভাইয়ের নামও বলবে। স্বর্গ থেকে মেরে ফেলা হয়েছে... ...তুমি নিজের উপর নির্ভর করে আছো, তার বই আমি করি তার বই তার বিষ ভাঙ্গার আগেই...","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏احْتَجَّ ‏ ‏آدَمُ ‏ ‏وَمُوسَى ‏ ‏قَالَ فَقَالَ ‏ ‏مُوسَى ‏ ‏يَا ‏ ‏آدَمُ ‏ ‏أَنْتَ الَّذِي خَلَقَكَ اللَّهُ بِيَدِهِ وَنَفَخَ فِيكَ مِنْ رُوحِهِ ‏ ‏أَغْوَيْتَ ‏ ‏النَّاسَ وَأَخْرَجْتَهُمْ مِنْ الْجَنَّةِ قَالَ فَقَالَ ‏ ‏آدَمُ ‏ ‏أَنْتَ ‏ ‏مُوسَى ‏ ‏أَنْتَ ‏ ‏اصْطَفَاكَ ‏ ‏اللَّهُ بِكَلَامِهِ تَلُومُنِي عَلَى عَمَلٍ أَعْمَلُهُ كَتَبَهُ اللَّهُ عَلَيَّ قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالْأَرْضَ قَالَ ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏","","",""],[8812,8812,"","আমরা বলেছিলাম, আমাদের সময় শেষ হবে, ঈশ্বর আমার বাবার ভালো করে দেখাতে ইচ্ছুক যে আমার প্রভু ঈশ্বর তার শান্তি এবং আমার ছেলে আমাকে ব্যর্থ করেছেন। আমি আশা করি আপনি শেষ হয়ে যাবেন। আমি আশা করি, আপনি যদি না থাকেন, আপনি শেষ হয়ে যান। আমি নিশ্চিত যে, আমার বাবা আমার ছেলে আপনার সাথে আছেন। আপনি কি না? আপনি কি মনে করেন, আপনি এখন আমার ছেলে না? আমি নিশ্চিত, আপনি শেষ হয়ে যাবেন? আমি নিশ্চিত যে, আপনি শেষ হয়ে যাবেন না। আমি নিশ্চিত, আপনি শেষ হয়ে যাবেন। আমি নিশ্চিত, আমি নিশ্চিত যে, আপনি শেষ হয়ে যাবেন না। আমি আপনাকে যে আপনি শেষ হয়ে যাবেন না। আমি জানি, আপনি কি করবেন না। আমি জানি, আমি জানি, আপনি কি করবেন, আপনি কি করবেন? আপনি কি করবেন? এবং আপনি কি করবেন? আপনি কি করবেন? আপনি কি করবেন? ঈশ্বরের নামে না চাইলেই ভালো হত, কিন্তু আমি দুঃখিত।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ ذَكْوَانَ يُكْنَى أَبَا الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏يَا ‏ ‏بَنِي هَاشِمٍ ‏ ‏اشْتَرُوا أَنْفُسَكُمْ مِنْ اللَّهِ عَزَّ وَجَلَّ لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا يَا ‏ ‏أُمَّ الزُّبَيْرِ عَمَّةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏فَاطِمَةُ بِنْتَ مُحَمَّدٍ ‏ ‏اشْتَرُوا أَنْفُسَكُمْ مِنْ اللَّهِ لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا سَلَانِي مِنْ مَالِي مَا شِئْتُمَا ‏","","",""],[8813,8813,"","আমি বলব যে আমার বাবার ভালবাসার জন্য দেবতা হওয়া, আমি এমন কিছুর মধ্যে হতে চাই যা তাকে পরিণত করবে। আর তার ফুসফুস","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أُحِبُّ أَنَّ ‏ ‏أُحُدًا ‏ ‏ذَاكُمْ يُحَوَّلُ ذَهَبًا يَكُونُ عِنْدِي بَعْدَ ثَلَاثٍ مِنْهُ شَيْءٌ إِلَّا شَيْئًا ‏ ‏أَرْصُدُهُ ‏ ‏لِدَيْنٍ إِنَّ الْأَكْثَرِينَ هُمْ الْأَقَلُّونَ يَوْمَ الْقِيَامَةِ إِلَّا مَنْ قَالَ هَكَذَا وَهَكَذَا وَهَكَذَا وَهَكَذَا وَقَلِيلٌ مَا هُمْ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ وَبَيْنَ يَدَيْهِ وَوَرَاءَهُ ‏","","",""],[8814,8814,"","আমরা বলতে চাই যে আমরা আমার বাবার ইচ্ছার ছেলে মানে, ঈশ্বরের কাছে নিজেকে সমর্পণ করতে হবে যদি আমি একে অপরের উপর বিশ্বাস করি। তার আদর্শের কথা উল্লেখ করার জন্য আমরা সিদ্ধান্ত নিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي ‏ ‏أَوْ عَلَى الْمُؤْمِنِينَ ‏ ‏لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ وَهُوَ ابْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏فَذَكَرَ مِثْلَهُ بِإِسْنَادِهِ ‏","","",""],[8815,8815,"","আমরা বলতে চাই যে আমরা আমার ভালোবাসার মূল্য অনেক বাড়িয়ে দিয়েছি একটি আশীর্বাদ ছেলের চেয়ে, ঈশ্বরের অবস্থা অনেক ভালো। সে তাকে একটা শর্টকাট বলে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُصَلِّيَ الرَّجُلُ ‏ ‏مُخْتَصِرًا ‏","","",""],[8816,8816,"","ঈশ্বর বলে দিয়েছেন যে, আমি যদি রাতের বেলা তোমাকে তাঁর প্রার্থনা খণ্ডন করতে বাধা দিই, তা হলে আমি তোমাকে কি তার সঙ্গে আরও বেশি কথা বলতে পারব?","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ اللَّيْلِ فَلْيَفْتَتِحْ صَلَاتَهُ بِرَكْعَتَيْنِ خَفِيفَتَيْنِ ‏","","",""],[8817,8817,"","আমরা আমাদের বাবার সঙ্গে যা ঘটেছে, সেই বিষয়ে কথা বলেছিলাম, সেই সময় চলে যাওয়ার কথা ছিল । সূর্যাস্ত হল এক গৌরব, আমি তোমাকে প্রার্থনা করতে শিক্ষা দিতে পারি।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ ذَكْوَانَ أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ قَبْلَ طُلُوعِ الشَّمْسِ سَجْدَةً فَقَدْ أَدْرَكَ الصَّلَاةَ وَمَنْ أَدْرَكَ قَبْلَ غُرُوبِ الشَّمْسِ سَجْدَةً فَقَدْ أَدْرَكَ الصَّلَاةَ ‏","","",""],[8818,8818,"","আমরা সবাই একজন বেপটিস্টের চেয়ে ভাল ছিলাম যে কখনো কথা বলেছে. আমার বাবা তার কাছে ঈশ্বরের কাছে প্রার্থনা করেছে যে সে তার শান্তি সমর্পণ করবে যদি আমি তোমার আত্মাতে প্রবেশ করি. আমি তার সেবাকে মদ খাওয়ার এবং পান করার জন্য তার সঙ্গে দেখা করার জন্য তাঁকে ডাকি না ।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُسْلِمٌ يَعْنِي ابْنَ خَالِدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ عَلَى أَخِيهِ الْمُسْلِمِ فَأَطْعَمَهُ طَعَامًا فَلْيَأْكُلْ مِنْ طَعَامِهِ وَلَا يَسْأَلْهُ عَنْهُ فَإِنْ سَقَاهُ شَرَابًا مِنْ شَرَابِهِ فَلْيَشْرَبْ مِنْ شَرَابِهِ وَلَا يَسْأَلْهُ عَنْهُ ‏","","",""],[8819,8819,"","আমি যদি তার কাছে আসি অথবা তার কাছে যাই, তাহলে তাকে ছেড়ে দিতে হবে, যদি তারা ঋণ ত্যাগ করে, তাহলে আমি তাদেরকে জিজ্ঞেস করব । আপনার কোম্পানির জন্য প্রার্থনা করুন এবং প্রার্থনা করুন ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ ‏ ‏أَوْ مُرَّ ‏ ‏عَلَيْهِ بِجِنَازَةٍ سَأَلَهُمْ هَلْ تَرَكَ دَيْنًا فَإِنْ قَالُوا نَعَمْ قَالَ هَلْ تَرَكَ وَفَاءً فَإِنْ قَالُوا نَعَمْ صَلَّى عَلَيْهِ وَإِنْ قَالُوا لَا قَالَ صَلُّوا عَلَى صَاحِبِكُمْ ‏","","",""],[8820,8820,"","বাবা একটা বল খনন করার চেষ্টা করছিল বলে আমরা কথা বলেছিলাম । সে তোমার পিছনে টাকা দেবে।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَجْتَمِعَانِ فِي النَّارِ أَبَدًا اجْتِمَاعًا يَضُرُّ أَحَدَهُمَا قَالُوا مَنْ يَا رَسُولَ اللَّهِ قَالَ مُؤْمِنٌ يَقْتُلُهُ كَافِرٌ ثُمَّ ‏ ‏يُسَدَّدُ ‏ ‏بَعْدَ ذَلِكَ ‏","","",""],[8821,8821,"","আর এই শিকারী ঈশ্বরের কাছে প্রার্থনা করেছিল যে, ঈশ্বর তার জীবনের জন্য নিশ্চিত ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَضَمَّنَ اللَّهُ لِمَنْ خَرَجَ فِي سَبِيلِهِ لَا يُخْرِجُهُ إِلَّا إِيمَانًا بِي وَتَصْدِيقًا بِرُسُلِي أَنْ أُدْخِلَهُ الْجَنَّةَ أَوْ أُرْجِعَهُ إِلَى مَسْكَنِهِ الَّذِي خَرَجَ مِنْهُ نَائِلًا مَا نَالَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ ‏","","",""],[8822,8822,"","ঈশ্বর তাঁর অনুগ্রহ লাভ করেছেন এবং তাঁর অনুগ্রহ লাভ করেছেন । আহত কিন্তু সে আমার বাবার জন্য ব্যাথা, বাবার জন্য একটা ঝামেলা, ঈশ্বরের জন্য একটা ঘোড়া তৈরি করেছে আর আমরা এই ব্যাপারে স্বপ্ন দেখছি।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ يُجْرَحُ فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ يُجْرَحُ فِي سَبِيلِهِ إِلَّا لَقِيَ اللَّهَ عَزَّ وَجَلَّ كَهَيْئَتِهِ يَوْمَ جُرِحَ لَوْنُهُ لَوْنُ دَمٍ وَرِيحُهُ رِيحُ مِسْكٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَ هَذَا الْحَدِيثِ ‏","","",""],[8823,8823,"","আমি যখন তাকে জিজ্ঞেস করি যে, আমি কী করতে পারি, তখন তিনি আমাকে সাহায্য করার জন্য কী করতে পারেন?","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ يُعْرَضُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقُرْآنَ فِي كُلِّ سَنَةٍ مَرَّةً فَلَمَّا كَانَ الْعَامُ الَّذِي قُبِضَ فِيهِ عُرِضَ عَلَيْهِ مَرَّتَيْنِ ‏","","",""],[8824,8824,"","আমরা আমার ছেলেকে নিয়ে কথা বলেছি, ঈশ্বর আমার ছেলেকে নিয়ে প্রার্থনা করেছেন, আর তিনি বলেছিলেন, যদি সে এটা খুঁজে পেতে রাজি হয় তাহলে তাকে আত্মসমর্পণ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنِيهِ ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَجْهَلْ فَإِنْ جُهِلَ عَلَيْهِ ‏ ‏فَلْيَقُلْ إِنِّي امْرُؤٌ صَائِمٌ ‏","","",""],[8825,8825,"","বাবা আমার বাবার সাথে কথা বলার চেষ্টা করে আমরা কথা বলেছিলাম। ঈশ্বর তার কাছে প্রার্থনা করেছিলেন এবং প্রার্থনা করে আমি প্রার্থনা করি যে, তিনি তাদের উপেক্ষা থেকে মুক্ত হবেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْرِدُوا بِالصَّلَاةِ فَإِنَّ فَيْحَهَا مِنْ حَرِّ جَهَنَّمَ ‏","","",""],[8826,8826,"","আমরা নখের ব্যাপারে কথা বলেছিলাম কিন্তু আমার ভাই বলেছিলেন, ঈশ্বর তাকে আদেশ দিয়েছেন আর ঈশ্বর তাকে ভালো প্রভু বলে কিছু বলবেন না। ছুরি দিয়ে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ حَسَّانَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُكْلَمُ ‏ ‏عَبْدٌ فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِهِ يَجِيءُ جُرْحُهُ يَوْمَ الْقِيَامَةِ لَوْنُهُ لَوْنُ دَمٍ وَرِيحُهُ رِيحُ مِسْكٍ ‏","","",""],[8827,8827,"","বেন আমাকে সাহায্য করতে পারবেন, তা জানতে পেরে আমি কথা বলেছিলাম । আমার বাবা একজন পলাতক যে হয়তো আমি ঘুম থেকে উঠে লিখতে ও লিখতে পারি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَلَاءِ الْحَسَنُ بْنُ سَوَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنْ كَانَ قَالَهُ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ الْوُضُوءِ ‏ ‏و قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لَقَدْ كُنْتُ ‏ ‏أَسْتَنُّ ‏ ‏قَبْلَ أَنْ أَنَامَ وَبَعْدَ مَا أَسْتَيْقِظُ وَقَبْلَ مَا آكُلُ وَبَعْدَ مَا آكُلُ حِينَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَا قَالَ ‏","","",""],[8828,8828,"","বাবা যখন আমাদের বাড়িতে আসেন, তখন আমরা বাবার সঙ্গে নাচতাম । আর তারপর বললো, \"ঈশ্বর, \"ঈশ্বর,\" সে বলল, \"আমি শুনেছি\", \"আমি শুনেছি\"।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَلَاءِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏نُعَيْمٍ الْمُجْمِرِ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَقِيتُ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَلَى ظَهْرِ الْمَسْجِدِ وَعَلَيْهِ سَرَاوِيلُ مِنْ تَحْتِ قَمِيصِهِ فَنَزَعَ سَرَاوِيلَهُ ثُمَّ تَوَضَّأَ وَغَسَلَ وَجْهَهُ وَيَدَيْهِ وَرَفَعَ فِي عَضُدَيْهِ الْوُضُوءَ وَرِجْلَيْهِ فَرَفَعَ فِي سَاقَيْهِ ثُمَّ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أُمَّتِي يَأْتُونَ يَوْمَ الْقِيَامَةِ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ آثَارِ الْوُضُوءِ فَمَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ ‏ ‏غُرَّتَهُ ‏ ‏فَلْيَفْعَلْ ‏","","",""],[8829,8829,"","আমরা রাজ্জার পতাকা খুঁজতে চেষ্টা করেছি, কিন্তু আমরা ইতিমধ্যে কথা বলেছি, তিনি আমার বাবার গোপন তথ্য অনুযায়ী তার চাচা মুসা বেনের অনুসন্ধান করছেন, যিনি তাকে বলেছেন যে ঈশ্বর তাকে এই কথা বলতে মানা করেছেন সে এটা করেছে, তুমি জানো না এখানে কী হতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الرَّازِيُّ ‏ ‏خَتَنُ ‏ ‏سَلَمَةَ الْأَبْرَشِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْفَضْلِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏مُوسَى بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمَنَّوْا لِقَاءَ الْعَدُوِّ فَإِنَّكُمْ لَا تَدْرُونَ مَا يَكُونُ فِي ذَلِكَ ‏","","",""],[8830,8830,"","আমরা ঈশ্বর হওয়ার বিষয়ে কথা বলেছিলাম এবং বলতে চাইলাম যে তিনি একজন উষ্ণ পিতা, কিন্তু তিনি ছিলেন শিকারী । প্রার্থনা, এবং দলকে একত্রিত হতে এবং বই এর ভাগ্যের বিরুদ্ধে যুদ্ধ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو صَخْرٍ حُمَيْدُ بْنُ زِيَادٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ إِسْحَاقَ ‏ ‏مَوْلَى ‏ ‏زَائِدَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ وَرَمَضَانُ إِلَى رَمَضَانَ مُكَفِّرَاتٌ مَا بَيْنَهُنَّ مَا اجْتُنِبَتْ الْكَبَائِرُ ‏","","",""],[8831,8831,"","আমার বাবা আমার বাবাকে নিয়ে একটা জলাঞ্জলি দিয়েছিলেন যে, তিনি একজন দেবী । ইয়েমেনের ভালো হবে, এতে কোন দোষ নেই।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ مُؤْلَفٌ وَلَا خَيْرَ فِيمَنْ لَا يَأْلَفُ وَلَا يُؤْلَفُ ‏","","",""],[8832,8832,"","আমরা মূসা সম্পর্কে কথা বলেছি আমার বাবার সম্পর্কে তিনি আপনার টাকা সম্পর্কে বলেছেন যে আমার বাবা ছেলে হবে কি না. সে বলবে যে অপরাধ দরজা তার মুখ ও দুই মুখ উড়িয়ে দিচ্ছে মুখ উড়িয়ে দাও, কিন্তু সে তার ভাইয়ের দয়া পেয়েছে... ...আমি ওদেরকে দু'বার গুলি করতে দেখতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ قُرِئَ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَبْوَابَ الْجَنَّةِ تُفْتَحُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ فَيُغْفَرُ لِكُلِّ عَبْدٍ لَا يُشْرِكُ بِاللَّهِ شَيْئًا إِلَّا رَجُلٌ بَيْنَهُ وَبَيْنَ أَخِيهِ ‏ ‏شَحْنَاءُ ‏ ‏فَيُقَالُ أَنْظِرُوهُمَا حَتَّى يَصْطَلِحَا مَرَّتَيْنِ ‏","","",""],[8833,8833,"","আমরা গিলানের সাথে কথা বলেছি, কথা বলার চেয়ে ভালো কথা বলার চেষ্টা করেছি। মানুষ অনুরোধ করেছে রাতে জয়ের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُفَضَّلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ زَحْرٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَيُّهَا النَّاسُ إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏فَرَضَ لَكُمْ عَلَى لِسَانِ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ فِي الْحَضَرِ أَرْبَعًا وَفِي السَّفَرِ رَكْعَتَيْنِ ‏","","",""],[8834,8834,"","আমরা আমার প্রাপ্তবয়স্ক বাবার সেরা বাবার ব্যাপারে কথা বলেছি, সে আমাকে বলেছে আমার বাবা তার শান্তি প্রতিষ্ঠা করেছেন বলে ঈশ্বর কিছু ভালো কাজ করেছেন। তারা তাদের শেষ হওয়ার পর থেকে আগুন পেতে। আমি আমার বাবা, আমার বাবা, আমার বাবা, আমাকে বলেছিলেন, ঈশ্বর তাঁর শান্তি দান করেছেন। আমি যদি আমার বাবা-মা তাঁর শান্তি চান, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি না যে আমি এটা করতে পারি। আমি যদি আমি এটা করি, আমি আমার বাবা আমাকে ছেড়ে চলে যেতে হবে। আমি কি করতে পারি? শহরে ফেলে দাও.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏صَالِحُ بْنُ أَبِي صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَتَحَمَّدَنَّ اللَّهُ يَوْمَ الْقِيَامَةِ عَلَى أُنَاسٍ مَا عَمِلُوا مِنْ خَيْرٍ قَطُّ فَيُخْرِجُهُمْ مِنْ النَّارِ بَعْدَمَا احْتَرَقُوا فَيُدْخِلُهُمْ الْجَنَّةَ بِرَحْمَتِهِ بَعْدَ شَفَاعَةِ مَنْ يَشْفَعُ ‏","","",""],[8835,8835,"","আমরা একবার মজা করার কথা বলেছিলাম, বাবা এর কারণ ছিল... ...আমি শুনেছি ঈশ্বর এসে গেছেন, সে বলছে সে চলে গেছে, তারা রাতের বেলা চাঁদকে আলো দিতে সাহায্য করবে একদিনে সে বললো, ঈশ্বর আমায় তাদের গড়ে তুলতে সাহায্য করুন।\" ঈশ্বর কি আমাকে তাদের থেকে আলাদা করবে, তুমি আমাকে বলবে, \"তুমি কেঁদেছ\"","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ الطَّالْقَانِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي ‏ ‏زُمْرَةٌ ‏ ‏هُمْ سَبْعُونَ أَلْفًا تُضِيءُ وُجُوهُهُمْ إِضَاءَةَ الْقَمَرِ لَيْلَةَ الْبَدْرِ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَقَامَ ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ الْأَسَدِيُّ ‏ ‏يَرْفَعُ ‏ ‏نَمِرَةً ‏ ‏عَلَيْهِ فَقَالَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ فَقَالَ اللَّهُمَّ اجْعَلْهُ مِنْهُمْ ثُمَّ قَامَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ ‏ ‏أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ سَبَقَكَ ‏ ‏عُكَّاشَةُ ‏","","",""],[8836,8836,"","আমরা তাকে আমাদের মারার চেষ্টা করেছিলাম । যে মহিলা খুন হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏وَعَلِيِّ بْنِ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَبِيصَةُ بْنُ ذُؤَيْبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُجْمَعَ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَبَيْنَ الْمَرْأَةِ وَخَالَتِهَا ‏","","",""],[8837,8837,"","বাবা বাবা হারাহ তার কথা শুনে তার সাথে কথা বলে, বাবা বলল যে তার আছে, দয়া তাদের বাবা-মা আর মন্দ আত্মাদের দ্বারা বন্দী হয়ে আছে ধরা পড়েছে.","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ أَبِي أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ رَمَضَانُ فُتِّحَتْ أَبْوَابُ الرَّحْمَةِ وَغُلِّقَتْ أَبْوَابُ جَهَنَّمَ ‏ ‏وَسُلْسِلَتْ ‏ ‏الشَّيَاطِينُ ‏","","",""],[8838,8838,"","আমরা ইশ্বরের সাথে কথা বলেছি আমরা ভয় পাব, আমার ধারণা সে বাবাকে একটা উৎকণ্ঠা বলতে শুনেছে যে এটা করতে বলা হয়েছে আর স্বপ্নের শিকার হতে নয়। তার লোক বলেছে তুমি জীবিতদের সবচেয়ে ভাল মানুষ... ...সে দেখেছে... ...আমরা তোমার আত্মাতে পাপ করেছি... ...আর তুমি জানো... দুঃখময় দরজা।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏فُلَانٍ الْخَثْعَمِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ سَفَرًا فَرَكِبَ ‏ ‏رَاحِلَتَهُ ‏ ‏قَالَ اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ ‏ ‏وَالْخَلِيفَةُ ‏ ‏فِي الْأَهْلِ ‏ ‏قَالَ وَأُرَاهُ قَالَ وَالْحَامِلُ عَلَى الظَّهْرِ ‏ ‏اللَّهُمَّ اصْحَبْنَا بِنُصْحٍ وَاقْلِبْنَا ‏ ‏بِذِمَّةٍ ‏ ‏أَعُوذُ بِكَ مِنْ مِلْحِ ‏ ‏وَعْثَاءِ ‏ ‏السَّفَرِ ‏ ‏وَكَآبَةِ ‏ ‏الْمُنْقَلَبِ ‏","","",""],[8839,8839,"","আমি আমার বাবার কথা বলি, একটা ঘোড়া আমার বাবার কথা শুনে কাঁদতে বলি, আমি তাকে বলতে চাই, আমি ঈশ্বরের সামনে প্রার্থনা করি এবং সে বলবে সে ঈশ্বরের মুখে আছে। সে নাকি তার একটা শপথ করে। আমি তাকে বলেছিলাম, আমি আমার বাবার কথা বলি, আমি তাকে বলেছিলাম, সে নাকি আমার বাবার কাছে প্রার্থনা করতে হবে। আমি তাকে বলেছিলাম, আমি তোমার কাছে একটা ঘোড়াও বলব, সে নাকি তোমার কাছে এটা একটা শপথ ছিল। আমি তোমার কাছে এটা একটা কথা বলব, কারণ তুমি জানো না যে, তুমি জানো, তুমি এটা আমার বাবার মত। তুমি জানো না। তুমি জানো না যে, তুমি জানো না, তুমি তোমার বাবা, তুমি আমাকে বলবে, তুমি জানো না। তুমি জানো না, তুমি তোমার বাবা, তুমি জানো না, তুমি জানো না, আমি তোমার কথা বলছি, আমি তোমার কথা বলছি। আমি তোমার কাছে এটা একটা ছোট কথা বলছি। ঈশ্বর, তার জন্য ঈশ্বরকে না বলে.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَجْلَحُ ‏ ‏أَنَّ ‏ ‏أَبَا بُرْدَةَ بْنَ أَبِي مُوسَى الْأَشْعَرِيَّ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ فِي الْجُمُعَةِ لَسَاعَةً مَا دَعَا اللَّهَ فِيهَا عَبْدٌ مُؤْمِنٌ بِشَيْءٍ إِلَّا اسْتَجَابَ اللَّهُ لَهُ ‏","","",""],[8840,8840,"","আমি ঈশ্বরকে বলেছি যে ফুলগুলো সম্পর্কে আমি আল্লাহ্‌কে বলতে পারি, আমি আল্লাহ্‌কে বলতে চাই, আমি বাবার কথা শুনেছি, সে ঈশ্বরের কাছে যাবে। সে তার কাছে এমন কথা বলে যে, সে ঈশ্বরের কাছে যাবে এবং সে তার মুক্তি পেয়েছে। তার বিশ্বাস অপরাধ স্বীকার করা হয়েছিল এবং তার নাক তার কাছ থেকে সরিয়ে নেওয়া হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ الْأَعْرَجُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ يَوْمٍ طَلَعَتْ فِيهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ فِيهِ خُلِقَ ‏ ‏آدَمُ ‏ ‏وَفِيهِ أُدْخِلَ الْجَنَّةَ وَفِيهِ أُخْرِجَ مِنْهَا ‏","","",""],[8841,8841,"","আমরা কথা বলেছিলাম যে ঈশ্বর তার সাথে ঘটেছে, ঈশ্বরের দয়ায়, আমার বাবার সাথে যুদ্ধ করতে পারার জন্য, তার নিজের ইচ্ছার সাথে যুদ্ধ করতে। অনেক চেষ্টা করা হয়েছে খুঁজে পেতে.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ الْأَعْرَجُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَهِدَ الْجِنَازَةَ حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ شَهِدَهَا حَتَّى تُدْفَنَ ‏ ‏وَقَالَ ‏ ‏عَتَّابٌ ‏ ‏حَتَّى تُفْرَغَ ‏ ‏فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏قِيلَ وَمَا ‏ ‏الْقِيرَاطَانِ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ ‏","","",""],[8842,8842,"","আমি ঈশ্বরকে বলেছি যে ফুলগুলো নিয়ে আমি কথা বলেছি আমি একজন ভালো বাবা আমি বলেছি ঈশ্বর তাকে প্রভুর কাছে হস্তান্তর করেছেন এবং পিলের কাছে ভয় পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏لَا يَصْبُغُونَ فَخَالِفُوهُمْ ‏","","",""],[8843,8843,"","আমি বাবার কুত্তি শুনতে শুনতে শুনতে চাই। সে বলবে, ঈশ্বর এটা লাইট দিয়ে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو إِدْرِيسَ الْخَوْلَانِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ ‏ ‏فَلْيَنْثُرْ ‏ ‏وَمَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏","","",""],[8844,8844,"","আমরা এক শিকারীর ছেলে, যে তোমার ঈশ্বরের ভালবাসার জন্য আমাদের সাথে কথা বলেছে, আমার বাবা আমাকে পছন্দ করেছে লর্ডের কথা শোনার পর।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ لَهِيعَةَ بْنِ عُقْبَةَ ‏ ‏وَعَنْ ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏لَهِيعَةَ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَرْدِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَإِيَّاكُمْ وَالْخَيْلَ ‏ ‏الْمُنَفِّلَةَ ‏ ‏فَإِنَّهَا إِنْ تَلْقَ تَفِرَّ وَإِنْ تَغْنَمْ ‏ ‏تَغْلُلْ ‏","","",""],[8845,8845,"","আমরা আমার ভাইকে খুঁজে বের করার কথা বলেছিলাম, যে আমার বাবার সাথে কথা বলেছে, যে বলেছে, সে বলে যে এটা করা উচিত আর তাকে পৃথিবীর দশ ভাগের একটার বেশি অর্থ দিতে হবে। সে মারা গেছে এবং সে থেমে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْتَكِفُ ‏ ‏الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ وَالْعَشْرَ الْأَوَاسِطَ فَمَاتَ حِينَ مَاتَ وَهُوَ ‏ ‏يَعْتَكِفُ ‏ ‏عِشْرِينَ يَوْمًا ‏","","",""],[8846,8846,"","আমার বাবা একজন পলাতক ছিলেন আর তিনি বলেছিলেন যে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং ঈশ্বর তা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ مَيْمُونٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي الْعُمَرِيَّ ‏ ‏عَنْ ‏ ‏جَهْمِ بْنِ أَبِي الْجَهْمِ ‏ ‏عَنْ ‏ ‏مِسْوَرِ بْنِ مَخْرَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ جَعَلَ الْحَقَّ عَلَى لِسَانِ ‏ ‏عُمَرَ ‏ ‏وَقَلْبِهِ ‏","","",""],[8847,8847,"","আমরা ঈশ্বরের চেয়ে উত্তম পুত্র হওয়ার বিষয়ে কথা বলেছিলাম, যিনি আমাকে একটা ঝড় জয় করতে বলেছিলেন । আমার বাবা একজন উৎপীড়ক ছিলেন যার তার স্বপ্ন ছিল, তুমি আমার জানা মতে ঐ অপরাধীকে থামানোর জন্য নয়.","‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ مَيْمُونٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَيْنَ مِنْبَرِي وَبَيْتِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَمِنْبَرِي عَلَى حَوْضِي ‏ ‏حَدَّثَنَا ‏ ‏نُوحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ إِلَّا أَنَّهُ قَالَ مِنْبَرِي ‏ ‏عَلَى تُرْعَةٍ مِنْ ‏ ‏تُرَعِ ‏ ‏الْجَنَّةِ ‏","","",""],[8848,8848,"","আমরা ঈশ্বরের কাছে কথা বলেছি মানে আমি ঈশ্বরের শপথের অভিজ্ঞতার জন্য অন্ধ। লর্ড তার কাছে প্রার্থনা করেছেন এবং আশ্বস্ত করেছেন যে মানুষ তাদের চিকিৎসা না হওয়া পর্যন্ত শহরে ফিরে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏نُوحٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي الْعُمَرِيَّ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُوشِكُ أَنْ يَرْجِعَ النَّاسُ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏حَتَّى تَصِيرَ ‏ ‏مَسَالِحُهُمْ ‏ ‏بِسِلَاحٍ ‏","","",""],[8849,8849,"","আমরা তোমাকে ঈশ্বরের অনুমতি নিয়ে উড়ি বলতে বলেছিলাম। আমার বাবা একটা উপহার যে আমার ঘোড়ারা ঘুমাতে যাওয়ার আগে আর প্রতিদিনের ঋতুর মতো।","‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ مَيْمُونٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي ‏ ‏خَلِيلِي ‏ ‏بِثَلَاثٍ ‏ ‏الْوَتْرِ ‏ ‏قَبْلَ النَّوْمِ وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَرَكْعَتَيْ الضُّحَى ‏","","",""],[8850,8850,"","আমরা কয়েক বার একে অন্যকে বলার চেষ্টা করেছিলাম । সে খুন করতে চায়নি, তারপর তোমার মা ফিরে আসল ভালো লোক ফিরে এসে তোমার বাবাকে বিদায় জানালো।","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا تَأْمُرُنِي قَالَ ‏ ‏بَرَّ ‏ ‏أُمَّكَ ثُمَّ عَادَ فَقَالَ ‏ ‏بَرَّ ‏ ‏أُمَّكَ ثُمَّ عَادَ الرَّابِعَةَ فَقَالَ ‏ ‏بَرَّ ‏ ‏أَبَاكَ ‏","","",""],[8851,8851,"","আমরা ঈশ্বরের সাথে কথা বলেছি কিন্তু ঈশ্বর হয়ত শুনতে পান আমার বাবা তার জন্য প্রার্থনা করেছেন, তাতে কোন সন্দেহ নেই যে গুহাতে এটা উপযুক্ত, না। নিজের পদক্ষেপ থেকে ছোট হয়ে থাকতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُؤْمِنٍ يُشَاكُ بِشَوْكَةٍ فِي الدُّنْيَا ‏ ‏يَحْتَسِبُهَا ‏ ‏إِلَّا قُصِّرَ بِهَا مِنْ خَطَايَاهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[8852,8852,"","আমরা একজন ভালো বন্ধুর ব্যাপারে কথা বলেছি কিন্তু আমরা দুই গ্রীষ্মের কথা শুনে খুশি হব। সে আমার বাবাকে ঈশ্বরের কাছ থেকে দূরে সরিয়ে দেবার স্বপ্ন দেখে। সে বলল যে, মানুষ কখনোই কথা বলবে না। ( মথি ৫: ৩, ৪) আপনার সম্বন্ধে কী বলা যায়?","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّبَيْرُ بْنُ سَعِيدٍ ‏ ‏فَذَكَرَ حَدِيثًا عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏قَالَ وَحَدَّثَ ‏ ‏صَفْوَانُ بْنُ سُلَيْمٍ ‏ ‏أَيْضًا ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ يُضْحِكُ بِهَا جُلَسَاءَهُ يَهْوِي بِهَا مِنْ أَبْعَدِ مِنْ ‏ ‏الثُّرَيَّا ‏","","",""],[8853,8853,"","আমরা কথা বলেছিলাম যে আমি তাকে বলতে যাচ্ছি আমার বাবা একজন কুমারী যিনি ঈশ্বরের কাছে প্রার্থনা করেছেন আর তিনি তার কাছে প্রার্থনা করেছেন তার কাছে, যাতে সে একটি ৯টা ভাষায় নিজেকে আত্মসমর্পণ না করে। এক মিনিট, বন্ধু, মোটা নয় পঞ্চম।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسُقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَا فِيمَا دُونَ خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَا فِيمَا دُونَ خَمْسِ ‏ ‏ذَوْدٍ ‏ ‏صَدَقَةٌ ‏","","",""],[8854,8854,"","আমরা ইশ্বরের সাহায্য নিয়ে কথা বলেছিলাম, আমার বাবা তার কাছে প্রার্থনা করেছিলেন... ...আর তিনি এটা বাড়ির উপর দিয়ে পাঠিয়ে দিতেন...","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏التَّلَقِّي ‏ ‏وَأَنْ يَبِيعَ حَاضِرٌ ‏ ‏لِبَادٍ ‏","","",""],[8855,8855,"","আমরা যে ফুল নিয়ে কথা বলেছিলাম, আমি বাবার কুত্তি শুনতে পাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ ‏ ‏الصَّدَقَةِ ‏ ‏مَا كَانَ عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏","","",""],[8856,8856,"","আমরা তাকে বলেছিলাম যে আমরা একদিন যেতে যাচ্ছি। কারণ সে বলছিল আমার বাবা ভালো মানুষ। আর আমি প্রভুর কাছে আত্মসমর্পন করব ।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ الطَّالْقَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يَقُولُ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْعَبْدِ الْمَمْلُوكِ الْمُصْلِحِ أَجْرَانِ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏بِيَدِهِ لَوْلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ وَالْحَجُّ ‏ ‏وَبِرُّ ‏ ‏أُمِّي ‏ ‏لَأَحْبَبْتُ أَنْ أَمُوتَ وَأَنَا مَمْلُوكٌ ‏","","",""],[8857,8857,"","ঈশ্বর বলেছিলেন যে, আমার সম্বন্ধে আমি দুজন ছেলেকে কিছু করার জন্য বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصِّيَامُ ‏ ‏جُنَّةٌ ‏ ‏وَحِصْنٌ حَصِينٌ مِنْ النَّارِ ‏","","",""],[8858,8858,"","আমরা চেষ্টা করেছি. বাচ্চাদের জন্য বিছানা।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَرِيرُ بْنُ يَزِيدَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا زُرْعَةَ بْنَ عَمْرِو بْنِ جَرِيرٍ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدٌّ يُعْمَلُ فِي الْأَرْضِ خَيْرٌ لِأَهْلِ الْأَرْضِ مِنْ أَنْ يُمْطَرُوا ثَلَاثِينَ صَبَاحًا ‏","","",""],[8859,8859,"","আমরা বলেছিলাম, হয়তো তৃতীয় দলটা বলেছিলাম। একটা ভবিষ্যদ্বাণীর জন্য তার কাছে প্রার্থনা করেছে... ...আর প্রভুর প্রভুর লর্ডকে উদ্ধার করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو ثِفَالٍ الْمُرِّيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْجَذَعُ ‏ ‏مِنْ الضَّأْنِ خَيْرٌ مِنْ السَّيِّدِ مِنْ الْمَعْزِ ‏ ‏قَالَ ‏ ‏دَاوُدُ ‏ ‏السَّيِّدُ الْجَلِيلُ ‏","","",""],[8860,8860,"","ঈশ্বর হয়তো তাকে ঈশ্বরের একজন দেবতা হিসেবে সম্বন্ধে বলেছিলেন এবং তার জন্য একজন দেবতা হিসেবে আমি তাকে বলতে পারি সে তাহাকে রক্ষা করিয়াছে, ভালুকটি ছুঁড়ে মার, কিন্তু তাহার কাছে মিথ্যা কথা কহিবে।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ رَافِعٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الرَّمِيَّةِ ‏ ‏أَنْ ‏ ‏تُرْمَى الدَّابَّةُ ثُمَّ تُؤْكَلَ وَلَكِنْ تُذْبَحُ ثُمَّ ‏ ‏لْيَرْمُوا إِنْ شَاءُوا ‏","","",""],[8861,8861,"","আমি আমার ভাইকে বলেছিলাম বিয়েটা নিয়ে আমি আমার ভাইকে বলেছি, আমি দুঃখিত আমি আমার মুখ ছেড়ে যেতে দেব না বলে। বিল্ডিংটি পুড়ে গেছে, এই ক্ষতিকর উপাদানের জন্য। সুইচ.","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏وَأَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَرَصَتْ نَمْلَةٌ نَبِيًّا مِنْ الْأَنْبِيَاءِ فَأَمَرَ بِقَرْيَةِ النَّمْلِ فَأُحْرِقَتْ فَأَوْحَى اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ فِي ‏ ‏أَنْ قَرَصَتْكَ نَمْلَةٌ أَهْلَكْتَ أُمَّةً مِنْ الْأُمَمِ تُسَبِّحُ ‏","","",""],[8862,8862,"","আমরা তাকে বলতে চাই তার থেকে ভাল ( গীতসংহিতা ৩৭: ১১) ঈশ্বর তাঁর প্রতিজ্ঞা পরিপূর্ণ করবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ ثَوْبَانَ ‏ ‏أُرَاهُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ وَرْدَانَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لِرَجُلٍ تَعَالَ ‏ ‏أُوَدِّعْكَ كَمَا وَدَّعَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ كَمَا وَدَّعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَوْدَعْتُكَ اللَّهَ الَّذِي لَا يُضَيِّعُ وَدَائِعَهُ ‏","","",""],[8863,8863,"","আমরা আপনাকে সিনিটিনিকিজমের সঙ্গে ধরতে চেষ্টা করেছি যে মেয়র আমাকে স্বপ্নের স্বপ্ন দিয়েছেন. সে বলবে, কেবল ইশ্বরই তার জন্য প্রার্থনা করেছে, আর সে আমার কাছে হার মানবে যেন সে এটা না করে, আমি বলতে চাই আমি আমার হাত লিখি না আর আমি ঈশ্বরের কাছে প্রার্থনা করি ( আদি.","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ بْنِ وَاقِدٍ الْحَرَّانِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏وَالْمُغِيرَةِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَا سَمِعْنَاهُ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ أَحَدٌ أَعْلَمَ بِحَدِيثِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنِّي إِلَّا مَا كَانَ مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏فَإِنَّهُ كَانَ يَكْتُبُ بِيَدِهِ ‏ ‏وَيَعِيهِ ‏ ‏بِقَلْبِهِ وَكُنْتُ ‏ ‏أَعِيهِ ‏ ‏بِقَلْبِي وَلَا أَكْتُبُ بِيَدِي ‏ ‏وَاسْتَأْذَنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْكِتَابِ عَنْهُ فَأَذِنَ لَهُ ‏","","",""],[8864,8864,"","আমরা কথা বলার চেষ্টা করলাম। ঈশ্বর তাকে বলেছেন আমি এ ব্যাপারে কথা বলেছি। আমার বাবা একজন সাহসী যে তার কাছে প্রার্থনা করে তাকে জেলে ভরার নামে বলবে না। বন্ধুত্বের পঞ্চম.","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسَاقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَيْسَ فِيمَا دُونَ خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَيْسَ فِيمَا دُونَ خَمْسِ ‏ ‏ذَوْدٍ ‏ ‏صَدَقَةٌ ‏","","",""],[8865,8865,"","আমরা রাজার আদর্শকে রক্ষা করার চেষ্টা করেছি, যখন আমরা কথা বলেছিলাম, আমার বাবা ছিলেন একজন দেবতা দেবতা, যে আমাকে বলেছে লর্ডের সাথে যা করতে। তোমার বাবা-মা তোমাকে বলতে চায় না যে সে শক্তিশালী হতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَلْجٍ يَحْيَى بْنُ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏أَنَّهُ حَدَّثَهُ قَالَ ‏ ‏قَالَ لِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُعَلِّمُكَ كَلِمَةً مِنْ كَنْزِ الْجَنَّةِ قَالَ قُلْتُ نَعَمْ فِدَاكَ أَبِي وَأُمِّي قَالَ قُلْ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[8866,8866,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমার বাবাকে বলতে চেয়েছিল, ঈশ্বর তাকে জিজ্ঞাসা করেছেন আর আমি যা করছি তা তাকে সমর্পণ করবো ঈশ্বরের দোহাইর উপর তিনি কখনও তার প্রভাব দেননি।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏ابْنِ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَنْعَمَ اللَّهُ عَلَى عَبْدٍ نِعْمَةً إِلَّا وَهُوَ يُحِبُّ أَنْ يَرَى أَثَرَهَا عَلَيْهِ ‏","","",""],[8867,8867,"","আমরা চেষ্টা করেছি আপনার রাজার হিজাব রক্ষা করার জন্য আমরা একটি স্বপ্ন রক্ষা করার জন্য. আমার বাবা একজন দেবতা যার জন্য আমি তোমাকে দিতে পারবো না. তিনি বললেন. তোমার পছন্দ আমি উড়ছি আর আমি তোমার অনুভূতি অনুভব করছি।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُنَبِّئُكُمْ بِخِيَارِكُمْ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏خِيَارُكُمْ أَطْوَلُكُمْ أَعْمَارًا وَأَحْسَنُكُمْ أَخْلَاقًا ‏","","",""],[8868,8868,"","আমরা Shariiyn এর পুত্র এর সাথে যা ঘটেছে তার ব্যাপারে কথা বলেছি, সে বলেছিল সে ঈশ্বরের দোহাই দিয়ে প্রার্থনা করবে এবং সে কৌশলের ব্যাপারে মাথা ঘামাবে। সুতরাং সে চাবুকটি নিয়ে নিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُتَلَقَّى الْجَلَبُ ‏ ‏فَإِنْ ‏ ‏ابْتَاعَ ‏ ‏مُبْتَاعٌ ‏ ‏فَصَاحِبُ السِّلْعَةِ ‏ ‏بِالْخِيَارِ ‏ ‏إِذَا وَرَدَتْ السُّوقَ ‏","","",""],[8869,8869,"","আমরা নিশ্চিত হয়েছি যে আমি পুরো একটা টোপের স্বপ্ন পূরণ করছি, যখন তার সময় বাবা হারাহর কথা শুনলাম যে সে আগে কখনো ঈশ্বরের কথা শোনে নি। শহরের একজন লোক, যারা শহর ছেড়ে চলে যেত তারা যদি শিখতে পারত তাহলে তাদের জন্য ভাল হতো.","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ اللُّؤْلُؤِيُّ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيَخْرُجَنَّ رِجَالٌ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏رَغْبَةً عَنْهَا ‏ ‏وَالْمَدِينَةُ ‏ ‏خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ ‏","","",""],[8870,8870,"","আমরা মূসা আমাকে বলেছেন যে আমার একটা ছেলে আছে বাবার ভালোর থেকে নিজেকে সরিয়ে নিতে। তাদের রাস্তায় নিয়ে যাও, সে জানে না সে কি পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ مَنَامِهِ ‏ ‏فَلْيُفْرِغْ ‏ ‏عَلَى يَدَيْهِ ثَلَاثَ مَرَّاتٍ قَبْلَ أَنْ يُدْخِلَهُمَا فِي الْإِنَاءِ فَإِنَّهُ لَا يَدْرِي فِيمَ بَاتَتْ يَدُهُ ‏","","",""],[8871,8871,"","আমরা আমার বাবার প্রতিবেশীদের সাথে কথা বলেছি তিনি বললেন যে তিনি বলছেন আমি ভাববাদীর কাছে প্রার্থনা করেছি আর তিনি এক ঘন্টার মধ্যেই মেঘে কথা বলবেন।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فِي يَوْمِ الْجُمُعَةِ سَاعَةٌ لَا ‏ ‏يُوَافِقُهَا ‏ ‏عَبْدٌ مُسْلِمٌ إِلَّا اسْتُجِيبَ لَهُ ‏","","",""],[8872,8872,"","আমরা মোশির সঙ্গে কথা বলেছিলাম যে আমার বাবা একজন জিনিয়াস । প্রার্থনা করে আরোগ্য লাভ করি।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ذَوَّادُ بْنُ عُلْبَةَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهَجِّرُ ‏ ‏قَالَ فَصَلَّيْتُ ثُمَّ جِئْتُ فَجَلَسْتُ إِلَيْهِ فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏اشِكَمَتْ ‏ ‏دَرْدْ ‏ ‏قَالَ قُلْتُ لَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏صَلِّ فَإِنَّ فِي الصَّلَاةِ شِفَاءً ‏","","",""],[8873,8873,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার পাপের কাছে নতিস্বীকার করেননি । আর বলেছে যে আমার ভাই বলেছিল এটা জিনিয়াস. যে ই একমাত্র সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি, যিনি ছিলেন সেই ব্যক্তি । সে ছিল সেই ব্যক্তি যে কিনা আমার ভাই বলেছিল, আমি তাকে জিজ্ঞেস করব। আর তুমি আমাকে হিংসা করেছ, আমি তোমার আর তোমার অনুগ্রহের আদেশ করছি... ...আমি আর তুমি আমার সব কিছুই শেষ করতে পারব না. সম্পূর্ণভাবে সম্পূর্ণভাবে মিলিয়ে ফেলা হবে, একেবারে অপুরোভাবে পুরো মিলিয়ে যাবে সম্পূর্ণভাবে সম্পূর্ণভাবে মিলিয়ে ফেলা হবে, একেবারে অপুরোভাবে পুরো মিলিয়ে যাবে সম্পূর্ণভাবে সম্পূর্ণভাবে মিলিয়ে ফেলা হবে, একেবারে অপুরোভাবে পুরো মিলিয়ে যাবে এরপর তিনি আমাকে বলেছিলেন যে, আপনি জানতেন আমি নিরাপদ এবং নিরাপদ আছি । কথা হল, তুমি বড় কাউকে নিয়ে যাবে, যে আমার বাবাকে বলেছে সে তার পাছার পেছনে দৌড়াচ্ছে আর বলেছে সে নাকি গডফাদার. সে বলেছে যে সে নাকি তাকে মেরে ফেলেছে. তার চোখে এবং তাকে একটা লড়াই দিতে বলেছে সে বলছে সে আবার গর্ভবতী হবে এবং আমি একটি জন্ম নিচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكْذِبْ ‏ ‏إِبْرَاهِيمُ ‏ ‏إِلَّا ثَلَاثَ كَذِبَاتٍ قَوْلُهُ حِينَ دُعِيَ إِلَى آلِهَتِهِمْ ‏ { ‏إِنِّي ‏ ‏سَقِيمٌ ‏ } ‏وَقَوْلُهُ ‏ { ‏فَعَلَهُ كَبِيرُهُمْ هَذَا ‏} ‏وَقَوْلُهُ ‏ ‏لِسَارَةَ ‏ ‏إِنَّهَا أُخْتِي قَالَ وَدَخَلَ ‏ ‏إِبْرَاهِيمُ ‏ ‏قَرْيَةً فِيهَا مَلِكٌ مِنْ الْمُلُوكِ ‏ ‏أَوْ جَبَّارٌ مِنْ الْجَبَابِرَةِ ‏ ‏فَقِيلَ دَخَلَ ‏ ‏إِبْرَاهِيمُ ‏ ‏اللَّيْلَةَ بِامْرَأَةٍ مِنْ أَحْسَنِ النَّاسِ قَالَ فَأَرْسَلَ إِلَيْهِ الْمَلِكُ ‏ ‏أَوْ الْجَبَّارُ ‏ ‏مَنْ هَذِهِ مَعَكَ قَالَ أُخْتِي قَالَ أَرْسِلْ بِهَا قَالَ فَأَرْسَلَ بِهَا إِلَيْهِ وَقَالَ لَهَا لَا تُكَذِّبِي قَوْلِي فَإِنِّي قَدْ أَخْبَرْتُهُ أَنَّكِ أُخْتِي إِنْ عَلَى الْأَرْضِ مُؤْمِنٌ غَيْرِي وَغَيْرُكِ قَالَ فَلَمَّا دَخَلَتْ إِلَيْهِ قَامَ إِلَيْهَا قَالَ فَأَقْبَلَتْ تَوَضَّأُ وَتُصَلِّي وَتَقُولُ اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنِّي آمَنْتُ بِكَ وَبِرَسُولِكَ وَأَحْصَنْتُ فَرْجِي إِلَّا عَلَى زَوْجِي فَلَا ‏ ‏تُسَلِّطْ ‏ ‏عَلَيَّ الْكَافِرَ قَالَ ‏ ‏فَغُطَّ ‏ ‏حَتَّى ‏ ‏رَكَضَ ‏ ‏بِرِجْلِهِ ‏ ‏قَالَ ‏ ‏أَبُو الزِّنَادِ ‏ ‏قَالَ ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهَا قَالَتْ اللَّهُمَّ إِنَّهُ إِنْ يَمُتْ يُقَلْ هِيَ قَتَلَتْهُ قَالَ فَأُرْسِلَ ثُمَّ قَامَ إِلَيْهَا فَقَامَتْ تَوَضَّأُ وَتُصَلِّي وَتَقُولُ اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنِّي آمَنْتُ بِكَ وَبِرَسُولِكَ وَأَحْصَنْتُ فَرْجِي إِلَّا عَلَى زَوْجِي فَلَا تُسَلِّطْ عَلَيَّ الْكَافِرَ قَالَ ‏ ‏فَغُطَّ ‏ ‏حَتَّى ‏ ‏رَكَضَ ‏ ‏بِرِجْلِهِ ‏ ‏قَالَ ‏ ‏أَبُو الزِّنَادِ ‏ ‏قَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهَا قَالَتْ اللَّهُمَّ إِنَّهُ إِنْ يَمُتْ يُقَلْ هِيَ قَتَلَتْهُ قَالَ فَأُرْسِلَ فَقَالَ فِي الثَّالِثَةِ ‏ ‏أَوْ الرَّابِعَةِ ‏ ‏مَا أَرْسَلْتُمْ إِلَيَّ إِلَّا شَيْطَانًا ارْجِعُوهَا إِلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَأَعْطُوهَا ‏ ‏هَاجَرَ ‏ ‏قَالَ فَرَجَعَتْ فَقَالَتْ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏أَشَعَرْتَ أَنَّ اللَّهَ عَزَّ وَجَلَّ رَدَّ كَيْدَ الْكَافِرِ وَأَخْدَمَ وَلِيدَةً ‏","","",""],[8874,8874,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি, আমার ভাই, আমরা একটা ছেলে যে আমাকে সাহায্য করবে, সে আমার কথা বলেছি। আমার বাবা আমাকে সাহায্য করবে। যে তাকে আদেশ করেছে এবং ঈশ্বর তাকে উদ্ধার করেছে এবং তিনি যে জন্য সে যে জিতে গেছে তার জন্য। আমি ভেবেছিলাম আমি একটা ছেলে ঘুম থেকে উঠে আসি নি যে বলল আমি ঈশ্বরের উপর দিয়ে যাচ্ছি। সে আমার কাছে ফিরে আসবে, আর সে আমার পা চুরি না করে। সে আমার জন্য যা খরচ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ اللَّهِ عَزَّ وَجَلَّ أَنَّهُ قَالَ ‏ ‏مَرِضْتُ فَلَمْ ‏ ‏يَعُدْنِي ‏ ‏ابْنُ ‏ ‏آدَمَ ‏ ‏وَظَمِئْتُ فَلَمْ يَسْقِنِي ابْنُ ‏ ‏آدَمَ ‏ ‏فَقُلْتُ أَتَمْرَضُ يَا رَبِّ قَالَ يَمْرَضُ الْعَبْدُ مِنْ عِبَادِي مِمَّنْ فِي الْأَرْضِ فَلَا يُعَادُ فَلَوْ ‏ ‏عَادَهُ ‏ ‏كَانَ مَا ‏ ‏يَعُودُهُ ‏ ‏لِي وَيَظْمَأُ فِي الْأَرْضِ فَلَا يُسْقَى فَلَوْ سُقِيَ كَانَ مَا سَقَاهُ لِي ‏","","",""],[8875,8875,"","আমরা মূসাকে কথা বলেছি আমার বাবা একজন ভালো ছেলে হওয়া সম্পর্কে। তাকে বলা হয়েছে যে সে শহরে প্রায় একশ বছর ধরে ছায়ার মধ্যে যাত্রী নিয়ে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ فِي الْجَنَّةِ لَشَجَرَةً يَسِيرُ الرَّاكِبُ ‏ ‏الْجَوَادُ ‏ ‏فِي ظِلِّهَا مِائَةَ سَنَةٍ وَإِنَّ وَرَقَهَا ‏ ‏لَيُخَمِّرُ ‏ ‏الْجَنَّةَ ‏","","",""],[8876,8876,"","আমি আমার বাবাকে একজন উৎপীড়ক বলে উল্লেখ করেছিলাম । কর্মকর্তাদের ভাড়া করে সৈন্যকে দোষারোপ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ وَرْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ مَاتَ ‏ ‏مُرَابِطًا ‏ ‏وُقِيَ فِتْنَةَ الْقَبْرِ وَأُومِنَ مِنْ الْفَزَعِ الْأَكْبَرِ ‏ ‏وَغُدِيَ عَلَيْهِ وَرِيحَ بِرِزْقِهِ مِنْ الْجَنَّةِ وَكُتِبَ لَهُ أَجْرُ ‏ ‏الْمُرَابِطِ ‏ ‏إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[8877,8877,"","আমরা এই চমক জয় করার চেষ্টা করেছি... ...আমরা সকালে আমরা যে অদ্ভুত জিনিস করেছি... ...সে কসম খেয়ে বলেছে যে, সে নাকি বাবার ছেলে হারাহরার ছেলের কাছে শপথ শুনেছে সে ঈশ্বরকে পাঠিয়েছে আর বলেছে যে সে এটা করেছে। প্রিয়ভাবে বন্ধুত্বকে চুম্বন করে আর মেনে নেয় না।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ صِبْرَةَ ‏ ‏وَعَبَّادُ بْنُ مَنْصُورٍ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقْبَلُ ‏ ‏الصَّدَقَةَ ‏ ‏وَلَا يَقْبَلُ مِنْهَا إِلَّا الطَّيِّبَ يَقْبَلُهَا بِيَمِينِهِ تَبَارَكَ وَتَعَالَى ‏ ‏وَيُرَبِّيهَا لِعَبْدِهِ الْمُسْلِمِ اللُّقْمَةَ كَمَا يُرَبِّي أَحَدُكُمْ ‏ ‏مُهْرَهُ ‏ ‏أَوْ ‏ ‏فَصِيلَهُ ‏ ‏حَتَّى ‏ ‏يُوَافَى ‏ ‏بِهَا يَوْمَ الْقِيَامَةِ مِثْلَ ‏ ‏أُحُدٍ ‏","","",""],[8878,8878,"","আমরা লর্ডের সাথে কথা বলেছি, আমরা একটা জীবন্ত ছেলের কথা বলেছি... ...আমি আমার বাবার কথা শুনেছি, একটা ভবিষ্যতবানীর জন্য তাকে আদেশ করা হয়েছে আর অপরাধ মাথায় আত্মসমর্পণ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ يَعْنِي إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏دَخَلَ عَبْدٌ الْجَنَّةَ بِغُصْنِ شَوْكٍ عَلَى ظَهْرِ طَرِيقِ الْمُسْلِمِينَ فَأَمَاطَهُ عَنْهُ ‏","","",""],[8879,8879,"","প্রভুর দিন নিয়ে আমরা কথা বলেছিলাম আমার বাবা দেবীর জন্য দেবতা হয়ে আছেন। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তাকে ঈশ্বরের অনুগ্রহের হিসাবে গ্রহণ করতে বলা হয়েছে। ঈশ্বরের প্রভু ও প্রভুদের প্রভু । যে লোক এই জন ্ য বেঁচে থাকবে সে-ই হবে সাহায ্ য করবে , আর যে হবে সে হবে ক ্ ষতিগ ্ রস ্ ত । সেই হবে সেই রাজা যে রাজা হবে। তুমি প্রথম এমন কিছুতে চুমু দিতে পারবে না যা তুমি হারবে না। ''আর আমরা তো গরীবদের থেকে গান গায়,","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَدْعُو عِنْدَ النَّوْمِ اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيمِ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ مُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ ‏ ‏فَالِقَ ‏ ‏الْحَبِّ وَالنَّوَى لَا إِلَهَ إِلَّا أَنْتَ أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ ‏ ‏بِنَاصِيَتِهِ ‏ ‏أَنْتَ الْأَوَّلُ لَيْسَ قَبْلَكَ شَيْءٌ وَأَنْتَ الْآخِرُ لَيْسَ بَعْدَكَ شَيْءٌ وَأَنْتَ الظَّاهِرُ لَيْسَ فَوْقَكَ شَيْءٌ وَأَنْتَ الْبَاطِنُ لَيْسَ دُونَكَ شَيْءٌ اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنْ الْفَقْرِ ‏","","",""],[8880,8880,"","আমরা তার বাবার কথা বলেছিলাম আমার ছেলের জন্য প্রার্থনা করার কথা, সে বলবে সে কখনোই ঋণ শোধ করবে না।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَسْتُرُ عَبْدٌ عَبْدًا فِي الدُّنْيَا إِلَّا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[8881,8881,"","আমার বাবার কথা বলেছিলাম, আমার বাবার কথা যেন সে আত্মসমর্পণ করে । তিনি বলেছিলেন যে, বন্যা এবং জল তাদের জীবন হারিয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏كَانَ ‏ ‏يَمُرُّ بِآلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِلَالٌ ثُمَّ هِلَالٌ لَا يُوقَدُ فِي شَيْءٍ مِنْ بُيُوتِهِمْ النَّارُ لَا لِخُبْزٍ وَلَا لِطَبِيخٍ فَقَالُوا بِأَيِّ شَيْءٍ كَانُوا يَعِيشُونَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ بِالْأَسْوَدَيْنِ التَّمْرِ وَالْمَاءِ وَكَانَ لَهُمْ جِيرَانٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَجَزَاهُمْ اللَّهُ خَيْرًا لَهُمْ ‏ ‏مَنَائِحُ ‏ ‏يُرْسِلُونَ إِلَيْهِمْ شَيْئًا مِنْ لَبَنٍ ‏","","",""],[8882,8882,"","আমরা আমার বাবার কথা বলেছিলাম, ঈশ্বরের মাধ্যমে প্রবেশের কথা বলছি, তুমি চলে যাওয়ার হুমকির মধ্যে আছো।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَهَادَوْا فَإِنَّ الْهَدِيَّةَ تُذْهِبُ ‏ ‏وَغَرَ ‏ ‏الصَّدْرِ ‏","","",""],[8883,8883,"","আমরা আমার বাবার সঙ্গে ঈশ্বরের বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَمَّرَ سِتِّينَ سَنَةً أَوْ سَبْعِينَ سَنَةً فَقَدْ ‏ ‏عُذِرَ ‏ ‏إِلَيْهِ فِي الْعُمُرِ ‏","","",""],[8884,8884,"","আমরা একটা দাসের চিন্তা নিয়ে কথা বলেছিলাম যেটা আমাদের চলে যেতে হয়েছে। একটা উপহার বলেছিল আমরা ঈশ্বরের ইচ্ছার সাথে গোপনে ছিলাম... সে সমাধান করতে পেরেছে, আমি তখন এটা নিতে চাই না।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنِ ‏ ‏الطُّهَوِيِّ ‏ ‏عَنْ ‏ ‏ذُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا فِي سَفَرٍ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْمَلْنَا ‏ ‏وَأَنْفَضْنَا ‏ ‏فَآتَيْنَا عَلَى إِبِلٍ ‏ ‏مَصْرُورَةٍ ‏ ‏بِلِحَاءِ ‏ ‏الشَّجَرِ ‏ ‏فَابْتَدَرَهَا ‏ ‏الْقَوْمُ لِيَحْلِبُوهَا فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذِهِ عَسَى أَنْ يَكُونَ فِيهَا ‏ ‏قُوتُ ‏ ‏أَهْلِ بَيْتٍ مِنْ الْمُسْلِمِينَ أَتُحِبُّونَ لَوْ أَنَّهُمْ أَتَوْا عَلَى مَا فِي ‏ ‏أَزْوَادِكُمْ ‏ ‏فَأَخَذُوهُ ثُمَّ قَالَ إِنْ كُنْتُمْ لَا بُدَّ فَاعِلِينَ فَاشْرَبُوا وَلَا تَحْمِلُوا ‏","","",""],[8885,8885,"","আমরা লর্ড নেকড়েদের কথা বলেছিলাম আমরা একটা ছেলের কথা বলব যে কিনা অনেক আগে জন্ম নিয়েছিল তার ছেলের জন্য একটা প্রতিজ্ঞা ছিল. ( পড়ুন, গীতসংহিতা ৩৪: ৬.)","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيلَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَدَعُوا رَكْعَتَيْ الْفَجْرِ وَإِنْ طَرَدَتْكُمْ الْخَيْلُ ‏","","",""],[8886,8886,"","আমি বাপ্তিস্ম নেওয়ার চেষ্টা করার বিষয়ে কথা বলেছিলাম, যার অর্থ আমার ছেলে ভুলের জন্য মূল্য দিতে পারে । এটার নাম উল্লেখ করা হয়েছে তাদের ফ্রেমের থেকে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْكِي عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏مَنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي وَمَنْ ذَكَرَنِي فِي مَلَإٍ مِنْ النَّاسِ ذَكَرْتُهُ فِي مَلَإٍ أَكْثَرَ مِنْهُمْ وَأَطْيَبَ ‏","","",""],[8887,8887,"","আমরা কিছু কৌশল করেছি, আমার বাবা একজন উৎপীড়ক ছিলেন... ...আর তাকে একটা পাগল হিসেবে চিহ্নিত করা হয়েছে আর তাকে বলতেই হবে যে আমি কি বলছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمَيْدَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا يَنْبَغِي لِعَبْدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏","","",""],[8888,8888,"","আমরা আমার বাবার উপর আমাদের বাবার উপর আঘাত করা সম্পর্কে কথা বলেছিলাম. সে বলেছে সে সম্ভবত তার কথা শুনেছে. সে বলেছিল সে বলেছিল সে বলেছিল সে তার কথা শুনলো. সে বলবে আমি হয়তো চলে যাব আর আমি চলে যাব. মনে হয় সে আমাকে ক্ষমা করবে না, হয়তো সে আবার চলে যাবে। হয়তো সে জানতো আমি ঈশ্বর আমার জন্য ক্ষমা প্রার্থনা করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَاصٌّ ‏ ‏يُقَالُ ‏ ‏لَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَمْرَةَ ‏ ‏قَالَ فَسَمِعْتُهُ يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ عَبْدًا ‏ ‏أَصَابَ ‏ ‏ذَنْبًا فَقَالَ أَيْ رَبِّ أَذْنَبْتُ ذَنْبًا فَاغْفِرْ لِي فَقَالَ رَبُّهُ عَزَّ وَجَلَّ ‏ ‏عَلِمَ عَبْدِي أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ وَيَأْخُذُ بِهِ فَغَفَرَ لَهُ ثُمَّ مَكَثَ مَا شَاءَ اللَّهُ ثُمَّ أَذْنَبَ ذَنْبًا آخَرَ فَقَالَ أَيْ رَبِّ أَذْنَبْتُ ذَنْبًا فَاغْفِرْهُ لِي فَقَالَ رَبُّهُ عَلِمَ عَبْدِي أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ وَيَأْخُذُ بِهِ قَدْ غَفَرْتُ لِعَبْدِي ‏","","",""],[8889,8889,"","আমি আমার বাবার সঙ্গে আমার ভাইয়ের জন্য মূল্য দেওয়ার চেষ্টা করি ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏زَكَرِيَّا ‏ ‏نَجَّارًا ‏","","",""],[8890,8890,"","আমরা যে - গুটিগুলো বলেছিলাম, সেগুলো নিয়ে আমরা কথা বলেছিলাম, যেগুলো একটা ছেলের অনুগ্রহ হারিয়ে ফেলেছিল । আর বলেছে তোমাকে যেতে না দিতে।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيلَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَدَعُوا رَكْعَتَيْ الْفَجْرِ وَإِنْ ‏ ‏طَرَدَتْكُمْ ‏ ‏الْخَيْلُ ‏","","",""],[8891,8891,"","আমরা কথা বলেছিলাম আমাকে বলতে যে আমি একটি বন্য জিনিস শুনেছি... ...ঈশ্বর তার জন্য প্রার্থনা করেছেন... ...এবং উপত্যকা আর পানির বল উৎসর্গ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏دَاوُدُ بْنُ فَرَاهِيجَ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ لَنَا طَعَامٌ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا الْأَسْوَدَانِ التَّمْرُ وَالْمَاءُ ‏","","",""],[8892,8892,"","আমরা বাবাকে রক্ষা করার চেষ্টা করেছিলাম, যেন ঈশ্বর তার কথা শোনেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الَّذِي يَسْمَعُ الْحِكْمَةَ وَيَتَّبِعُ شَرَّ مَا يَسْمَعُ كَمَثَلِ رَجُلٍ أَتَى رَاعِيًا فَقَالَ لَهُ ‏ ‏أَجْزِرْنِي ‏ ‏شَاةً مِنْ غَنَمِكَ فَقَالَ اذْهَبْ فَخُذْ بِأُذُنِ خَيْرِهَا شَاةً فَذَهَبَ فَأَخَذَ بِأُذُنِ كَلْبِ الْغَنَمِ ‏","","",""],[8893,8893,"","পৃথিবীর দুঃখগুলো আমাদের গান গাওয়ার এবং মৃত্যুর টোপের জন্য আহ্বান জানায় আর তিনি সেটা পাঠান ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏النُّعْمَانُ بْنُ رَاشِدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏شَرُّ الطَّعَامِ طَعَامُ ‏ ‏الْوَلِيمَةِ ‏ ‏يُدْعَى لَهَا الْأَغْنِيَاءُ وَيُدْفَعُ ‏ ‏عَنْهَا الْفُقَرَاءُ وَمَنْ تَرَكَ الدَّعْوَةَ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[8894,8894,"","আমরা একটার কথা বলেছিলাম কিন্তু একজন শিকারী বলেছিল যে আমরা ফুল সম্বন্ধে কথা বলেছি । কথা শুনে ভালো লাগল.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏طِيَرَةَ ‏ ‏وَخَيْرُهَا الْفَأْلُ قَالُوا يَا رَسُولَ اللَّهِ وَمَا الْفَأْلُ قَالَ الْكَلِمَةُ الصَّالِحَةُ يَسْمَعُهَا أَحَدُكُمْ ‏","","",""],[8895,8895,"","আমরা আমার ভালবাসার কথা বলেছিলাম, ঈশ্বরকে প্রার্থনা করতে বললো, সে তাকে চিনত না, আর সে অসুস্থ হতে চাইবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُورَدُ ‏ ‏مُمْرِضٌ عَلَى ‏ ‏مُصِحٍّ ‏","","",""],[8896,8896,"","আমরা একটা ঘোড়ার কথা বলেছিলাম, যিনি বাবা হারলিকে একজন যাজক বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أُتِيَ بِطَعَامٍ مِنْ غَيْرِ أَهْلِهِ سَأَلَ عَنْهُ فَإِنْ قِيلَ هَدِيَّةٌ أَكَلَ وَإِنْ قِيلَ ‏ ‏صَدَقَةٌ ‏ ‏قَالَ كُلُوا وَلَمْ يَأْكُلْ ‏","","",""],[8897,8897,"","তিনি বলেছিলেন যে, ঈশ্বর তাঁর জন্য প্রার্থনা করেছিলেন এবং তিনি যে - আলো চেয়েছিলেন, তা অনুভব করতে তিনি তাঁর কাছে প্রার্থনা করেছিলেন । বিদায় জানাতে বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏رَأَى رَجُلًا مُبَقَّعَ الرِّجْلَيْنِ فَقَالَ أَحْسِنُوا الْوُضُوءَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏","","",""],[8898,8898,"","আমরা একটি তালা মেরে বলার কথা বললাম, আমি বাবাকে বলতে শুনেছি যে আমি আল্লাহ্‌ আদেশ দিয়েছেন আর বলবো রবি বলেছেন যে মহান জাতির উন্নতি আর মঙ্গলের জন্য। আর যে তাকে কিনেছিল সে জোর করে বলেছিল যে সে তাকে পাশ থেকে থামাতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الدَّابَّةُ ‏ ‏الْعَجْمَاءُ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏ ‏وَمَنْ ابْتَاعَ شَاةً فَوَجَدَهَا ‏ ‏مُصَرَّاةً ‏ ‏فَهُوَ ‏ ‏بِالْخِيَارِ ‏ ‏إِنْ شَاءَ رَدَّهَا ‏ ‏وَصَاعًا ‏ ‏مِنْ تَمْرٍ ‏","","",""],[8899,8899,"","আমরা হামাদের সাথে কথা বলেছি কিন্তু আমাদের বলতে বলা হয়েছে যে, একজন শিকারী আমাদের তার ভাইয়ের নামে বাপ্তাইজিত করেছে। শপথটা তাকে আদেশ করেছে আর আমি বন্ধুত্বের অনুগ্রহে সেনেতা। তার ভাষণ তাকে তাকে জিজ্ঞেস করেছিল যে সে যদি তোমাকে মুক্ত করে, তাহলে সে তোমাকে কি তাকে দেখতে চাইবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِتَمْرٍ مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَأَمَرَ فِيهِ بِأَمْرِهِ فَحَمَلَ ‏ ‏الْحَسَنَ ‏ ‏أَوْ ‏ ‏الْحُسَيْنَ ‏ ‏عَلَى ‏ ‏عَاتِقِهِ ‏ ‏فَجَعَلَ لُعَابُهُ يَسِيلُ عَلَيْهِ فَنَظَرَ إِلَيْهِ فَإِذَا هُوَ يَلُوكُ تَمْرَةً فَحَرَّكَ خَدَّهُ وَقَالَ أَلْقِهَا يَا بُنَيَّ أَمَا شَعَرْتَ ‏ ‏أَنَّ آلَ ‏ ‏مُحَمَّدٍ ‏ ‏لَا يَأْكُلُونَ ‏ ‏الصَّدَقَةَ ‏","","",""],[8900,8900,"","আমরা আমার বাবার কথা বলেছিলাম আমার ভাই দেবতা হওয়া নিয়ে কথা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَمَّارُ بْنُ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَطَاعَ الْعَبْدُ رَبَّهُ وَسَيِّدَهُ فَلَهُ أَجْرَانِ ‏","","",""],[8901,8901,"","আমি যা শুনেছি তা কখনোই কোন উৎপীড়ক ছিল না, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং যদি তিনি আপনার সেবা করতে আসেন তাহলে তিনি আত্মসমর্পণ করবেন যদি তিনি আপনার মুক্তির জন্য আপনার সেবা করতে আসেন, আমি তাকে বলছি না। আমি তাকে বলছি না যে, আপনি যদি আপনি আমাকে বলেন যে তিনি আমাকে বলছেন, আপনি তাকে ক্ষমা করে দেন। তার খাবারও।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَمَّارُ بْنُ أَبِي عَمَّارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَاءَ خَادِمُ أَحَدِكُمْ بِطَعَامِهِ قَدْ كَفَاهُ ‏ ‏حَرَّهُ ‏ ‏وَعَمَلَهُ فَإِنْ لَمْ يُقْعِدْهُ مَعَهُ لِيَأْكُلَ فَلْيُنَاوِلْهُ أُكْلَةً مِنْ طَعَامِهِ ‏","","",""],[8902,8902,"","আমরা কথা বলেছিলাম যে ঈশ্বর একজন কুমারী, ঈশ্বর তাঁর নিজের মা আর তার বাবা একজন দেবতা, আমার কোন ছেলে ছিল না ভাববাদী এবং তিনি যদি তাকে একজন মানুষ হিসেবে দেখেন, তা হলে তিনি বিজয়ী হয়েছিলেন । তার অন্ধকার জায়গা, হাতি এবং বাঘের সাথে কালো হয়ে যায় এবং আপনি যে গানটি জিতে যান এবং আপনার জয়ে জয়েন করেন তার সাথে গান গেয়ে যান।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ آدَمَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَنْبِيَاءُ إِخْوَةٌ لِعَلَّاتٍ ‏ ‏أُمَّهَاتُهُمْ شَتَّى وَدِينُهُمْ وَاحِدٌ وَأَنَا أَوْلَى النَّاسِ ‏ ‏بِعِيسَى ابْنِ مَرْيَمَ ‏ ‏لِأَنَّهُ لَمْ يَكُنْ بَيْنِي وَبَيْنَهُ نَبِيٌّ وَإِنَّهُ نَازِلٌ فَإِذَا رَأَيْتُمُوهُ فَاعْرِفُوهُ رَجُلًا ‏ ‏مَرْبُوعًا ‏ ‏إِلَى الْحُمْرَةِ وَالْبَيَاضِ عَلَيْهِ ثَوْبَانِ ‏ ‏مُمَصَّرَانِ ‏ ‏كَأَنَّ رَأْسَهُ يَقْطُرُ وَإِنْ لَمْ يُصِبْهُ بَلَلٌ فَيَدُقُّ الصَّلِيبَ وَيَقْتُلُ الْخِنْزِيرَ وَيَضَعُ الْجِزْيَةَ وَيَدْعُو النَّاسَ إِلَى الْإِسْلَامِ فَيُهْلِكُ اللَّهُ فِي زَمَانِهِ الْمِلَلَ كُلَّهَا إِلَّا الْإِسْلَامَ وَيُهْلِكُ اللَّهُ فِي زَمَانِهِ ‏ ‏الْمَسِيحَ الدَّجَّالَ ‏ ‏وَتَقَعُ الْأَمَنَةُ عَلَى الْأَرْضِ حَتَّى ‏ ‏تَرْتَعَ ‏ ‏الْأُسُودُ مَعَ الْإِبِلِ ‏ ‏وَالنِّمَارُ مَعَ الْبَقَرِ وَالذِّئَابُ مَعَ الْغَنَمِ وَيَلْعَبَ الصِّبْيَانُ بِالْحَيَّاتِ لَا تَضُرُّهُمْ فَيَمْكُثُ أَرْبَعِينَ سَنَةً ثُمَّ يُتَوَفَّى وَيُصَلِّي عَلَيْهِ الْمُسْلِمُونَ ‏","","",""],[8903,8903,"","আমরা হামাদ বান সেলমার সাথে কথা বলেছি, আমরা শিকারীর নামে বাপ্তাইজিত হয়েছি অথবা শিকারীর সেল ধ্বংস করার চেষ্টা করেছি। যে কিনা জেলে যেতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏عَجِبَ رَبُّنَا عَزَّ وَجَلَّ مِنْ رِجَالٍ يُقَادُونَ إِلَى الْجَنَّةِ فِي السَّلَاسِلِ ‏","","",""],[8904,8904,"","ঈশ্বর এটা করেছেন এবং অনেক আগে থেকেই তিনি তা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى قَبْرٍ ‏","","",""],[8905,8905,"","আমরা কথা বলেছিলাম গোলাম হিসেবে আমার কথা শুনতে। সে বাবাকে বলতে শুনেছে... ...তার কথা ও ঈশ্বরের কাছে প্রার্থনা করেছে। ঈশ্বরকে বলে, ঈশ্বর আমার কেটে ফেলেছে। আর আমি ভুল। আর আমি ভুল। আমি কি জানি? আমি কি? আমি জানি, তুমি জানো, তুমি কি? তুমি জানো, তুমি কি আমাকে তোমার কথা বলো? তুমি জানো, তুমি জানো, তুমি জানো, তুমি জানো, তুমি জানো না তুমি কি আমাকে? তুমি জানো, তুমি জানো, তুমি যদি তুমি আমার কথা বলো, তুমি জানো, তুমি জানো, তুমি জানো, তুমি আমার বাবা, তুমি আমাকে তোমার বাবা-মাগের কাছে বলবে, তুমি জানো না। তুমি জানো, তুমি আমাকে বলবে, তুমি জানো না তুমি জানো, তুমি জানো, তুমি জানো না তুমি আমাকে তোমার কথা বলবে, তুমি জানো, তুমি জানো না তোমার বাবা আমার বাবা বলবে, আমি তোমার বাবা-মা আমার কথা শুনতে পেয়েছে। তুমি জানো না। আমি তোমার কাছে এটা তোমার কাছে এটা একটা বড় কথা শুনেছি। আর আমি তোমার কাছে একটা প্রশ্ন করে। কে কাটলো?","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْجَبَّارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ كَعْبٍ الْقُرَظِيَّ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ ‏ ‏الرَّحِمَ ‏ ‏شُجْنَةٌ ‏ ‏مِنْ الرَّحْمَنِ تَقُولُ يَا رَبِّ إِنِّي قُطِعْتُ يَا رَبِّ إِنِّي أُسِيءَ إِلَيَّ يَا رَبِّ إِنِّي ظُلِمْتُ يَا رَبِّ قَالَ فَيُجِيبُهَا ‏ ‏أَمَا تَرْضَيْنَ أَنْ أَصِلَ مَنْ وَصَلَكِ وَأَقْطَعَ مَنْ قَطَعَكِ ‏","","",""],[8906,8906,"","আমরা বাবার সাথে কথা বলেছিলাম আমার বাবার মুক্তির কথা। ঈশ্বরের শক্তি দিয়ে তিনি যা বলেছিলেন তা হলো ঈশ্বরের জীবনের কোর্টে শোনা। জাহান্নামের জগগগগগগ্ধ পথ আছে আর তার নিজের হাতে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ قَوْمٍ يَجْتَمِعُونَ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ عَزَّ وَجَلَّ يَقْرَءُونَ وَيَتَعَلَّمُونَ كِتَابَ اللَّهِ عَزَّ وَجَلَّ يَتَدَارَسُونَهُ بَيْنَهُمْ إِلَّا ‏ ‏حَفَّتْ ‏ ‏بِهِمْ الْمَلَائِكَةُ ‏ ‏وَغَشِيَتْهُمْ ‏ ‏الرَّحْمَةُ وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ وَمَا مِنْ رَجُلٍ يَسْلُكُ طَرِيقًا ‏ ‏يَلْتَمِسُ ‏ ‏بِهِ الْعِلْمَ إِلَّا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ وَمَنْ يُبْطِئُ بِهِ عَمَلُهُ لَا يُسْرِعُ بِهِ نَسَبُهُ ‏","","",""],[8907,8907,"","আমরা বলেছিলাম বাবা হাররি আমাকে বলতে বলেছে যে তিনি আমাকে আল্লাহ্‌র কথা মেনে নিয়েছেন, তিনি প্রতিজ্ঞা করেছেন যে বধির আমি আল্লাহ্‌র লর্ড অফ লর্ড অফ লর্ড অফ লর্ডকে দোষারোপ করছি প্রভুর কাছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلِيمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[8908,8908,"","আমরা মসজিদ সম্পর্কে কথা বলেছি কিন্তু আমার বাবা একজন উৎপীড়ক ছিলেন। আল্লাহ তাঁর জন্য প্রার্থনা করেছেন। আমরা ওকে মেরে ফেলবো, মুক্ত কর!","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو الْمُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجٍّ ‏ ‏أَوْ عُمْرَةٍ ‏ ‏فَاسْتَقْبَلَتْنَا ‏ ‏رِجْلٌ ‏ ‏مِنْ جَرَادٍ فَجَعَلْنَا نَضْرِبُهُنَّ بِسِيَاطِنَا وَعِصِيِّنَا نَقْتُلُهُنَّ فَسُقِطَ فِي أَيْدِينَا فَقُلْنَا مَا صَنَعْنَا وَنَحْنُ مُحْرِمُونَ فَسَأَلْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا بَأْسَ صَيْدُ الْبَحْرِ ‏","","",""],[8909,8909,"","আমরা বলতে চাই যে হামাদ বেনের স্বপ্নের কথা শুনে ঘোড়া বা তার কথা শোনা বা শোনা যায় না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏طَعَامُ الْوَاحِدِ يَكْفِي ‏ ‏الِاثْنَيْنِ وَطَعَامُ ‏ ‏الِاثْنَيْنِ يَكْفِي الْأَرْبَعَةَ ‏","","",""],[8910,8910,"","প্রভু তার কাছে প্রার্থনা করেছিলেন এবং বলেছিলেন যে, তারা তার মহিমার মাধ্যমে ছয় বছরেরও বেশি সময় ধরে তার প্রতি অনুগ্রহ করবে ঋণটা আমার বিশেষ এক আদেশ। আর আমাকে বলতে হবে যদি আমি সার্ভিসের মাধ্যমে যাই।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ رِيَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا ‏ ‏بِالْأَعْمَالِ سِتًّا طُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا ‏ ‏وَالدَّجَّالَ ‏ ‏وَالدُّخَانَ وَدَابَّةَ الْأَرْضِ ‏ ‏وَخُوَيْصَّةَ ‏ ‏أَحَدِكُمْ وَأَمْرَ الْعَامَّةِ ‏ ‏وَكَانَ ‏ ‏قَتَادَةُ ‏ ‏يَقُولُ ‏ ‏إِذَا قَالَ وَأَمْرَ الْعَامَّةِ قَالَ أَيْ أَمْرُ السَّاعَةِ ‏","","",""],[8911,8911,"","আমরা আমার বাবা, একজন যাজক, আমাদের ঈশ্বর সম্পর্কে কথা বলেছিলাম। সে যখন বাপ্তিস্ম লাভ করবে তখন আত্মসমর্পণ করবে যখন সে বলেছিল যে সে স্বর্গে যাচ্ছে আর সে চলে যাবে না। অপরাধীরা কখনো কানের উপর গুলিয়ে যায়নি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْسِبُ ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏إِنَّهُ مَنْ يَدْخُلْ الْجَنَّةَ يَنْعَمْ وَلَا يَبْأَسْ لَا ‏ ‏تَبْلَى ‏ ‏ثِيَابُهُ وَلَا ‏ ‏يَفْنَى شَبَابُهُ فِي الْجَنَّةِ مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ ‏","","",""],[8912,8912,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি উত্তম বিশ্বাসের বিষয়ে চিন্তা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ نَهَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حُسْنُ الظَّنِّ مِنْ حُسْنِ الْعِبَادَةِ ‏","","",""],[8913,8913,"","আমরা আমাদের কথাবার্তার বিষয়ে কথা বলেছিলাম এবং তিনি আমার বাবার সঙ্গে আপনার টাকা নিয়ে কথা বলেছিলেন । তার দয়া।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خُثَيْمُ بْنُ عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ فِي عَبْدِ الرَّجُلِ وَلَا فِي فَرَسِهِ ‏ ‏صَدَقَةٌ ‏","","",""],[8914,8914,"","আমার বাবা আমাকে একটা ভবিষ্যদ্বাণীর উপহার দিয়েছিলেন, যে তাকে আদেশ দিয়েছিল আর তিনি যখন একটা জিনিস পেয়ে যান তখন তাকে উদ্ধার করা হবে । লোকটা আংটি বিক্রি করছিল, সসেজকে ফেলার কাল্পনিক ছিল, তারপর সে চলে গেল এবং চলে গেল, আর জাহাজে আটকে গেছে। অর্ধেক হুইসেল.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْسِبُ ‏ ‏حَمَّادٌ ‏ ‏أَنَّ ‏ ‏رَجُلًا كَانَ يَبِيعُ الْخَمْرَ فِي سَفِينَةٍ وَمَعَهُ فِي السَّفِينَةِ قِرْدٌ فَكَانَ يَشُوبُ الْخَمْرَ بِالْمَاءِ قَالَ فَأَخَذَ الْقِرْدُ الْكِيسَ ثُمَّ صَعِدَ بِهِ فَوْقَ الدُّورِ وَفَتَحَ الْكِيسَ فَجَعَلَ يَأْخُذُ دِينَارًا فَيُلْقِهِ فِي السَّفِينَةِ وَدِينَارًا فِي الْبَحْرِ حَتَّى جَعَلَهُ نِصْفَيْنِ ‏","","",""],[8915,8915,"","আমরা হামাদ বান সিজনস সম্পর্কে কথা বলেছি, আমরা বলি বাউদাকে দেবী বলতে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏رَأَى رَجُلًا مُبَقَّعَ الرِّجْلَيْنِ فَقَالَ أَحْسِنُوا الْوُضُوءَ فَإِنِّي سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْعَقِبِ ‏ ‏مِنْ النَّارِ ‏","","",""],[8916,8916,"","তিনি আমার ভালবাসার কথা বলেছেন, আর তিনি আমার ভালবাসার কথা বলেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَاحِبٌ لَنَا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ نَهَى عَنْ صَوْمِ يَوْمِ الْجُمُعَةِ إِلَّا صَوْمًا مُتَتَابِعًا ‏","","",""],[8917,8917,"","আমরা একটা ঘোড়ার কথা বলতে চেষ্টা করেছি যেটা হয়ত খোদাকে হারিয়েছে। ঈশ্বর আমার বাবা, ঈশ্বর একজন দেবতা, একজন দেবী, তাদের চোখ দিয়ে তার হাত কেটে ফেলেছে। প্রভু এবং আমার বাবার অনুগ্রহের শোকের দ্বারা সে উদ্ধার হবে, যারা সমাধান করতে পারে না এবং কোন উপায় পছন্দ করে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ إِبْرَاهِيمَ الْقُرَشِيِّ ‏ ‏أَوْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ الْقُرَشِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو فِي ‏ ‏دُبُرِ ‏ ‏صَلَاةِ الظُّهْرِ ‏ ‏اللَّهُمَّ خَلِّصْ ‏ ‏الْوَلِيدَ بْنَ الْوَلِيدِ ‏ ‏وَسَلَمَةَ بْنَ هِشَامٍ ‏ ‏وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ ‏ ‏وَضَعَفَةَ الْمُسْلِمِينَ مِنْ أَيْدِي الْمُشْرِكِينَ الَّذِينَ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا ‏","","",""],[8918,8918,"","বেনের প্রতি দয়া দেখানো নিয়ে আমরা কথা বলেছি যখন আমরা কথা বলি তিনি কি ভাল করেছেন, আমি ঈশ্বরের কাছে প্রার্থনা করব আর তাকে সঠিক হাত এবং রাজার রাজা দেবেন। ওই কুঠরীগুলো তোমার সামনে এসে পড়ে... ...যে তোমার কাছে এমন কেউ আছে যে তুমি বলেছিলে যে সে ঐ কামনা আর কামনাকে ধরে ফেলেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِيمَانُ يَمَانٍ وَالْكُفْرُ قِبَلَ الْمَشْرِقِ ‏ ‏وَالسَّكِينَةُ ‏ ‏فِي أَهْلِ الْغَنَمِ وَالْفَخْرُ ‏ ‏وَالرِّيَاءُ ‏ ‏فِي ‏ ‏الْفَدَّادِينَ ‏ ‏يَأْتِي ‏ ‏الْمَسِيحُ ‏ ‏مِنْ قِبَلِ الْمَشْرِقِ وَهِمَّتُهُ ‏ ‏الْمَدِينَةَ ‏ ‏حَتَّى إِذَا جَاءَ ‏ ‏دُبُرَ ‏ ‏أُحُدٍ ‏ ‏ضَرَبَتْ ‏ ‏الْمَلَائِكَةُ وَجْهَهُ قِبَلَ ‏ ‏الشَّامِ ‏ ‏هُنَالِكَ يَهْلِكُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً صَرَفَتْ الْمَلَائِكَةُ وَجْهَهُ ‏","","",""],[8919,8919,"","আমরা আমার বাবার কথা বলেছিলাম তিনি কি করে বলেছিলেন তিনি তার স্বপ্নের কথা বললেন তিনি বললেন তিনি তার জন্য প্রার্থনা করতেন আর তিনি এগিয়ে আসতে পারতেন না, এটা ডিজাইন নয়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقَدَّمُوا بَيْنَ يَدَيْ رَمَضَانَ بِصَوْمِ يَوْمٍ وَلَا يَوْمَيْنِ إِلَّا رَجُلٌ كَانَ صِيَامَهُ فَلْيَصُمْهُ ‏","","",""],[8920,8920,"","( পড়ুন, গীতসংহিতা ৩৪: ১ - ৩.)","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَامَ رَمَضَانَ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏فَإِنَّهُ يُغْفَرُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[8921,8921,"","সে বলেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর সে ভাগ্যের কাছে আত্মসমর্পণ করবে, সে বলেছে আমরা একটা ছেলেকে একই ভাবে বলেছিলাম।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏فَإِنَّهُ يُغْفَرُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَحَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏بِمِثْلِهِ ‏","","",""],[8922,8922,"","আমরা হামাদ বান সালেমের বিচার নিয়ে কথা বলেছি। ঈশ্বরের কাছে প্রার্থনা করছি, তাকে উদ্ধার করতে হবে। তিনি বলবেন, ইতোমধ্যে তিনি নারী ছিলেন অথবা নারী নন। ঈশ্বর প্রার্থনা এবং সালাদের জন্য আশীর্বাদ নিয়ে এসেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَكِيمٌ الْأَثْرَمُ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏أَتَى ‏ ‏حَائِضًا أَوْ امْرَأَةً فِي ‏ ‏دُبُرِهَا ‏ ‏أَوْ ‏ ‏كَاهِنًا ‏ ‏فَصَدَّقَهُ فَقَدْ بَرِئَ مِمَّا أَنْزَلَ اللَّهُ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏","","",""],[8923,8923,"","আমরা আমার বাবার সাথে কথা বলেছিলাম আমার প্রিয় বাবার কথা। আমি বলতে চাই, \"ঈশ্বর\" বলতে গেলে সে বলতে পারে আমি এটাকে পছন্দ করি, আমি তোমাকে কত ভালবাসি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا رَفَعَهُ ثُمَّ قَالَ ‏ ‏حَمَّادٌ ‏ ‏أُرَاهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا زَارَ أَخًا لَهُ فِي قَرْيَةٍ أُخْرَى ‏ ‏فَأَرْصَدَ ‏ ‏اللَّهُ عَلَى ‏ ‏مَدْرَجَتِهِ ‏ ‏مَلَكًا فَلَمَّا أَتَى عَلَيْهِ قَالَ الْمَلَكُ أَيْنَ تُرِيدُ قَالَ أَزُورُ أَخًا لِي فِي هَذِهِ الْقَرْيَةِ قَالَ هَلْ لَهُ عَلَيْكَ مِنْ نِعْمَةٍ ‏ ‏تَرُبُّهَا ‏ ‏قَالَ لَا إِلَّا أَنِّي أَحْبَبْتُهُ فِي اللَّهِ عَزَّ وَجَلَّ قَالَ فَإِنِّي ‏ ‏يَعْنِي رَسُولُ اللَّهِ إِلَيْكَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَحَبَّكَ كَمَا أَحْبَبْتَهُ ‏","","",""],[8924,8924,"","আমরা শেষবারের মতো কথা বলেছিলাম যে সে আমাদের যেতে বলেছে, ঈশ্বরের অনুগ্রহ থেকে একটা ঘোড়া তাকে তার শান্তিয় আত্মসমর্পন করেছে আর পরের বার আত্মসমর্পণ করেছে। আত্মসমর্পণ করো, আমি নিশ্চিত আমরা আমাদের ভাই-ভাইকে দেখতে পাব আমরা নই, আমি চেষ্টা করবো এবং যারা ফিরে না যায় তাদের সাথে বিশ্বাসঘাতকতা করব, আর আমাকে কিছু একটা বুঝতে হবে। সে একটা কৌশলী ঘোড়া নিয়ে এসেছিল, তার ইচ্ছা নিয়ে... ...ঈশ্বর বললেন সে আলোকে ঈর্ষা করবে... ...আর আমি তোমাকে ভেঙ্গে ফেলব. ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمَقْبَرَةِ فَسَلَّمَ عَلَى أَهْلِهَا قَالَ ‏ ‏سَلَامٌ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ وَدِدْتُ أَنَّا قَدْ رَأَيْنَا إِخْوَانَنَا قَالُوا أَوَلَسْنَا إِخْوَانَكَ يَا رَسُولَ اللَّهِ قَالَ بَلْ أَنْتُمْ أَصْحَابِي وَإِخْوَانِي الَّذِينَ لَمْ يَأْتُوا بَعْدُ وَأَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ قَالُوا وَكَيْفَ تَعْرِفُ مَنْ لَمْ يَأْتِ بَعْدُ مِنْ أُمَّتِكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏أَرَأَيْتَ ‏ ‏لَوْ أَنَّ رَجُلًا لَهُ خَيْلٌ ‏ ‏غُرٌّ ‏ ‏مُحَجَّلَةٌ ‏ ‏بَيْنَ ظَهْرَيْ خَيْلٍ ‏ ‏دُهْمٍ ‏ ‏بُهْمٍ ‏ ‏أَلَا يَعْرِفُ خَيْلَهُ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَإِنَّهُمْ يَأْتُونَ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ الْوُضُوءِ يَقُولُهَا ثَلَاثًا وَأَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ أَلَا ‏ ‏لَيُذَادَنَّ ‏ ‏رِجَالٌ عَنْ حَوْضِي كَمَا ‏ ‏يُذَادُ ‏ ‏الْبَعِيرُ الضَّالُّ ‏ ‏أُنَادِيهِمْ أَلَا ‏ ‏هَلُمَّ ‏ ‏أَلَا ‏ ‏هَلُمَّ ‏ ‏فَيُقَالُ إِنَّهُمْ قَدْ بَدَّلُوا بَعْدَكَ فَأَقُولُ ‏ ‏سُحْقًا ‏ ‏سُحْقًا ‏","","",""],[8925,8925,"","তিনি ঈশ্বরের সঙ্গে এক বিয়ের বিষয়ে বলেছিলেন, যে - বিয়েতে তিনি এতটাই বৃদ্ধ ছিলেন যে, তিনি ঈশ্বরের সঙ্গে এক শান্তি পেয়েছিলেন । একবার বিখ্যাত হয়ে উঠেছিলো এমন এক স্বপ্নের কথা বলেছিলেন যে, আপনি এটা বলতে পারবেন না যে, আপনি তা করতে পারবেন না । তাদের ডাকতে আমার কাছে তোমার রাজার ইচ্ছার কথা বলার জন্য, বাবা, আমি তার সাথে আছি আর সে আমার প্রভুর সিংহাসনের মাধ্যমে আমার অনুগ্রহ হারিয়েছে, তাকে একটা ফোন করতে হবে, তিনি বলেছিলেন, তিনি ঈশ্বরকে বলেন এবং আমাকে শিক্ষা দিতে বলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَزْرَقِ ‏ ‏أَنَّهُ ‏ ‏كَانَ مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏جَالِسًا ذَاتَ يَوْمٍ بِالسُّوقِ فَمُرَّ بِجِنَازَةٍ ‏ ‏يُبْكَى عَلَيْهَا فَعَابَ ذَلِكَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَانْتَهَرَهُمْ فَقَالَ لَهُ ‏ ‏سَلَمَةُ بْنُ الْأَزْرَقِ ‏ ‏لَا تَقُلْ ذَلِكَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏فَأَشْهَدُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏لَسَمِعْتُهُ وَتُوُفِّيَتْ امْرَأَةٌ مِنْ ‏ ‏كَنَائِنِ ‏ ‏مَرْوَانَ ‏ ‏فَشَهِدَهَا ‏ ‏مَرْوَانُ ‏ ‏فَأَمَرَ بِالنِّسَاءِ اللَّاتِي يَبْكِينَ فَضُرِبْنَ فَقَالَ لَهُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏دَعْهُنَّ يَا ‏ ‏أَبَا عَبْدِ الْمَلِكِ ‏ ‏فَإِنَّهُ مُرَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ ‏ ‏يُبْكَى عَلَيْهَا وَأَنَا مَعَهُ وَمَعَهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَحِمَهُ اللَّهُ فَانْتَهَرَ ‏ ‏عُمَرُ ‏ ‏اللَّاتِي يَبْكِينَ مَعَ الْجِنَازَةِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُنَّ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏فَإِنَّ ‏ ‏النَّفْسَ مُصَابَةٌ وَإِنَّ الْعَيْنَ دَامِعَةٌ وَإِنَّ الْعَهْدَ لَحَدِيثٌ ‏ ‏قَالَ ‏ ‏أَنْتَ سَمِعْتَهُ فَقَالَ نَعَمْ قَالَ اللَّهُ وَرَسُولُهُ أَعْلَمُ ‏","","",""],[8926,8926,"","আমার বাবা একজন আশীর্বাদজনক ব্যক্তি আর তিনি বলবেন যে, তিনি এই গাছের সুখী পরিবেশকে উপভোগ করতে পারবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو كَثِيرٍ الْعَنْبَرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ مِنْ النَّخْلَةِ وَالْعِنَبَةِ ‏","","",""],[8927,8927,"","আমার বসের প্রেমিককে হত্যা করার ব্যাপারে আমরা কথা বলেছি। আমার বাবা একটা উপন্যাসের কথা জেনেই তার কাছে প্রার্থনা করেছেন। তার প্রভু তার দায়িত্ব সম্পর্কে আমার প্রভুত্বের সাক্ষী হতে পারে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏صَاحِبُ ‏ ‏الزِّيَادِيِّ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ أَهْلِ الْعِلْمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَا مِنْ مُسْلِمٍ يَمُوتُ فَيَشْهَدُ لَهُ ثَلَاثَةُ أَهْلِ أَبْيَاتٍ مِنْ جِيرَانِهِ الْأَدْنَيْنَ بِخَيْرٍ إِلَّا قَالَ تَبَارَكَ وَتَعَالَى قَدْ ‏ ‏قَبِلْتُ شَهَادَةَ عِبَادِي عَلَى ‏ ‏مَا عَلِمُوا وَغَفَرْتُ لَهُ مَا أَعْلَمُ ‏","","",""],[8928,8928,"","আমার ভাইয়ের সবচেয়ে ভালো কথা বলেছি, আমার ছেলেকে বলে দিয়েছে সে কেমন আছে। আমি সেই মিথ্যার আশ্রয় দিচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَزَادَنِي ‏ ‏غَيْرُ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْذَبُ النَّاسِ الصُّنَّاعُ ‏","","",""],[8929,8929,"","ঈশ্বর তার কাছে প্রার্থনা করেছিলেন এবং সেই গাছের ও অভিশাপ থেকে পঞ্চম জনকে উদ্ধার করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ الْغُبَرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ النَّخْلَةِ وَالْعِنَبَةِ ‏","","",""],[8930,8930,"","আমরা একটি পুত্র কথা বলেছি যে আমার সুখের সময় আমার কাছে টাকা এনেছে। সম্ভবত নবী প্রার্থনা করলেন, \"ঈশ্বর, আমি জন্ম নিয়েছি\" আমরা জানি। তিনি বললেন, \"তোমার প্রভু ঈশ্বরের কাছে যা বলেছেন, আল্লাহ তার প্রতি দয়া করুন।\" তিনি বললেন তিনি এটা করেছেন এবং তিনি তা করেছেন.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ امْرَأَتِي وَلَدَتْ غُلَامًا أَسْوَدَ فَقَالَ ‏ ‏هَلْ لَكَ مِنْ إِبِلٍ قَالَ نَعَمْ قَالَ فَمَا أَلْوَانُهَا قَالَ ‏ ‏رُمْكٌ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرُبَّمَا لَيْسَ جَاءَتْ بِالْبَعِيرِ ‏ ‏الْأَوْرَقِ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ نَعَمْ قَالَ فَأَنَّى ‏ ‏تَرَى ذَلِكَ قَالَ أُرَاهُ ‏ ‏نَزَعَهُ ‏ ‏عِرْقٌ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَذَا ‏ ‏نَزَعَهُ ‏ ‏عِرْقٌ ‏","","",""],[8931,8931,"","আমরা কথা বলেছিলাম যে ভয় পেয়ে আমরা কথা বলেছি আমরা প্রভুর মৃত্যুর থ্রেড নিয়ে। আমি আমার যাত্রা পর্যন্ত আমার অনুমতি চাচ্ছি। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং ঈশ্বরের কাছে প্রার্থনা করেছেন, যিনি হয়তো নিজেকে গুপ্ত স্থানে রেখেছেন এবং তাকে অপূর্ব বিষয় জানাতে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏بِطَرِيقِ ‏ ‏مَكَّةَ ‏ ‏إِذْ هَاجَتْ رِيحٌ فَقَالَ لِمَنْ حَوْلَهُ الرِّيحَ قَالَ فَلَمْ يَرُدُّوا عَلَيْهِ شَيْئًا قَالَ فَبَلَغَنِي الَّذِي سَأَلَ عَنْهُ مِنْ ذَلِكَ فَاسْتَحْثَثْتُ رَاحِلَتِي حَتَّى أَدْرَكْتُهُ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ بَلَغَنِي أَنَّكَ سَأَلْتَ عَنْ الرِّيحِ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الرِّيحُ مِنْ رَوْحِ اللَّهِ فَلَا تَسُبُّوهَا وَسَلُوا خَيْرَهَا وَاسْتَعِيذُوا بِهِ مِنْ شَرِّهَا ‏","","",""],[8932,8932,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি যে আমাদের দাঙ্গা হয়েছে, আমি যে উত্তর শুনেছি তার চেয়ে বেশি বধিরদের কথা শুনেছি। আমার বাবা একজন পলাতক। আমি দেখেছি যে... ...ঈশ্বর তার কাছে প্রার্থনা করেছেন... ...আর তাকে ছেড়ে চলে যাবার পর তাকে আত্মসমর্পণ করতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَزِيدَ بْنَ الْأَصَمِّ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏بِالْمَدِينَةِ ‏ ‏مَعَ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏فَمَرَّتْ بِهِمَا جِنَازَةٌ فَقَامَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَلَمْ يَقُمْ ‏ ‏مَرْوَانُ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتْ بِهِ جِنَازَةٌ ‏ ‏فَقَامَ فَقَامَ عِنْدَ ذَلِكَ ‏ ‏مَرْوَانُ ‏","","",""],[8933,8933,"","আমরা আমাদের মনের কষ্ট সহ্য করতে একটি আবেগ আরোগ্য করতে চেষ্টা করেছি। ভবিষ্যদ্বাণীর জন্য তার জন্য প্রার্থনা করা হয়েছে। আমি তার জন্য প্রার্থনা করছি এবং আমি এটা ছেড়ে যেতে ভালোর জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ نَهَى عَنْ ‏ ‏الْفَرَعِ ‏ ‏وَالْعَتِيرَةِ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَقَدْ سَمِعْتُهُ أَنَا مِنْ ‏ ‏مَعْمَرٍ ‏","","",""],[8934,8934,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...আমরা তার ভাইয়ের ভাইয়ের কথা শুনেছি, শিকারীর প্রতি আবেগ নিয়ে... ...আর তার ভাইয়ের ভাইয়ের জন্য প্রার্থনা করেছি। স্টোন বাঞ্চ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْوَلَدُ لِصَاحِبِ ‏ ‏الْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏","","",""],[8935,8935,"","আমরা একটা আবেগ কথা বলেছি যা আমাদের জন্য একটা ঘোড়ার জন্য একটা হার্টবিট এনেছে, যে কিনা এটা শুনেছিল। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার মায়ের কাছে আমার সকল মহৎতার জন্য তাকে আত্মসমর্পণ করবেন, উত্তর দেওয়ার জন্য তুমি আমার মায়ের কাছে গুজব বলতে পারো, শক্তির মৃত্যু।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِكُلِّ نَبِيٍّ دَعْوَةٌ دَعَا بِهَا فِي أُمَّتِهِ فَيُسْتَجَابُ لَهُ وَإِنِّي ‏ ‏أُرِيدُ إِنْ شَاءَ اللَّهُ أَنْ أُؤَخِّرَ دَعْوَتِي ‏ ‏شَفَاعَةً ‏ ‏لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏","","",""],[8936,8936,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমাদের কাছে ঘোড়ার দাস হওয়া একটা অনুভূতি নিয়ে এসেছে যেটা বলেছে যে সে কুমারী। তারা এই প্রক্রিয়ায় মারা যাচ্ছে, তারা বলছে তারা বাতি জ্বালিয়ে দিতে যাচ্ছে। আগুন থেকে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَأْتِي عَلَى النَّاسِ وَهُمْ يَتَوَضَّئُونَ فِي الْمَطْهَرَةِ فَيَقُولُ لَهُمْ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ فَإِنِّي سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏","","",""],[8937,8937,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের একজন শিকারীের করুণা ধারণ করতে নিয়ে এসেছে। শহর বলেছে, তিনি এমন একজন ব্যক্তিকে দেখেছেন যিনি তার সাথে দেখা করতে আসবেন এবং তারপর তিনি তার টাওয়ারে আঘাত করবেন এবং তারপর বললেন তিনি বলেছেন, কিন্তু, সেই যাজকের কাছে প্রার্থনা করা হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مَرْوَانُ ‏ ‏يَسْتَعْمِلُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ فَكَانَ إِذَا رَأَى إِنْسَانًا يَجُرُّ إِزَارَهُ ضَرَبَ بِرِجْلِهِ ثُمَّ يَقُولُ قَدْ جَاءَ الْأَمِيرُ قَدْ جَاءَ الْأَمِيرُ ثُمَّ يَقُولُ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَى مَنْ جَرَّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏","","",""],[8938,8938,"","আমরা এক আবেগে বাপ্তাইজিত হয়েছি, যে কিনা ঘোড়া শুনতে পেয়েছে, সে তার জন্য প্রার্থনা করেছে, আর সে তাদের সবাইকে আত্মসমর্পণ করবে যাতে তারা সবাই যেতে পারে - খুশি হবেন না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَحْفِهِمَا جَمِيعًا أَوْ أَنْعِلْهُمَا جَمِيعًا فَإِذَا لَبِسْتَ فَابْدَأْ بِالْيَمِينِ وَإِذَا خَلَعْتَ فَابْدَأْ بِالْيُسْرَى ‏","","",""],[8939,8939,"","আমরা একটি আবেগ দ্বারা বাপ্তাইজিত যে আমরা একটি শিকারী একটি প্রথা আনা হয় যে একটি শিকারী যে শোনা বা শোনা. ঈশ্বর তা উদ্ধার করতে হবে এবং আমি তার দাস সঙ্গে তার সেবা করতে হবে তার নিজের সন্দেহ আছে তাকে মুক্ত করে দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ أَحَدَكُمْ خَادِمُهُ بِطَعَامٍ فَإِنْ لَمْ يُجْلِسْهُ مَعَهُ فَلْيُنَاوِلْهُ أُكْلَةً أَوْ أُكْلَتَيْنِ ‏ ‏أَوْ لُقْمَةً أَوْ لُقْمَتَيْنِ ‏ ‏شُعْبَةُ ‏ ‏شَكَّ ‏ ‏فَإِنَّهُ ‏ ‏وَلِيَ ‏ ‏عِلَاجَهُ ‏ ‏وَحَرَّهُ ‏","","",""],[8940,8940,"","আমরা আমাদের আবেগে বাপ্তাইজিত হয়েছি, যা আমার বাবার কাজের মাধ্যমে ঘটেছে, একটা ঘোড়া যা আমার কাছে শপথ নিয়েছে। বন্ধুত্বের মাধ্যমে সে তার সাথে যায়, ঈশ্বরের কাছে মুক্তি পাওয়া যাবে, আর আমি তার কাছে আত্মসমর্পণ করব, আমরা বন্ধুত্ব করব না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏الْحَسَنَ ‏ ‏أَخَذَ تَمْرَةً مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَجَعَلَهَا فِي ‏ ‏فِيهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِخْ كِخْ أَلْقِهَا أَمَا شَعَرْتَ ‏ ‏أَنَّا أَهْلَ بَيْتٍ لَا نَأْكُلُ ‏ ‏الصَّدَقَةَ ‏","","",""],[8941,8941,"","বাবার ইচ্ছার প্রতি আমার প্রবল আগ্রহ আছে, আমার বাবার শপথ নিতে হবে অথবা আমি সব থেকে ভালো মানুষ হব. তিনি যা বলেছিলেন, তার প্রতি ঈর্ষা, নাকি তিনি এবং আমি অন্যান্য শব্দ ছেড়ে দেব","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏لَوْ أَنَّ ‏ ‏الْأَنْصَارَ ‏ ‏سَلَكُوا وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏وَسَلَكَ النَّاسُ وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا ظَلَمَ بِأَبِي وَأُمِّي لَقَدْ آوَوْهُ وَنَصَرُوهُ وَكَلِمَةً أُخْرَى ‏","","",""],[8942,8942,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি, যা আমাদের বাবার সতীত্ব নিয়ে ঈর্ষার অনুভূতি এনে দিয়েছে, আল্লাহ তা উদ্ধার করতে হবে এবং বলবে তুমি এটা গান গাইতে পারবে না চোখ দিয়ে সে তার সাথে চলে আসে, আর তাকে বিক্রি না করে তার ভাই বিক্রি করে না। তাই তার টাকা কখনোই লেখা হয়নি এবং সে বেঁচে যাবে না। ...যে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏تُصَرُّوا ‏ ‏الْإِبِلَ وَالْغَنَمَ فَمَنْ اشْتَرَى ‏ ‏مُصَرَّاةً ‏ ‏فَهُوَ بِأَحَدِ ‏ ‏النَّظَرَيْنِ ‏ ‏إِنْ شَاءَ رَدَّهَا وَرَدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ قَالَ وَلَا يَبِيعُ الرَّجُلُ عَلَى بَيْعِ أَخِيهِ وَلَا تَسْأَلُ الْمَرْأَةُ طَلَاقَ أُخْتِهَا ‏ ‏لِتَكْتَفِئَ ‏ ‏مَا فِي صَحْفَتِهَا فَإِنَّ مَالَهَا مَا كُتِبَ لَهَا وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا ‏ ‏تَلَقَّوْا الْأَجْلَابَ ‏","","",""],[8943,8943,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি যা আমার ছেলের মুক্তির সংকল্প সম্পর্কে এসেছে। ফিরে এসেই সে শেষ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَجَّ هَذَا ‏ ‏الْبَيْتَ ‏ ‏فَلَمْ ‏ ‏يَرْفُثْ ‏ ‏وَلَمْ يَفْسُقْ رَجَعَ كَمَا وَلَدَتْهُ أُمُّهُ ‏","","",""],[8944,8944,"","আমরা আমাদের আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...আমরা একটা রীতির কথা বলছি... ...যে আমার ভালোবাসা আমার কাছে, তার কাছে প্রার্থনা করে, কোন ঘটনা বা বাতাস থেকে আলো আসছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا وُضُوءَ إِلَّا مِنْ ‏ ‏حَدَثٍ ‏ ‏أَوْ رِيحٍ ‏","","",""],[8945,8945,"","আমরা ঈশ্বরের প্রতি আমার দৃঢ় প্রেম নিয়ে কথা বলেছি। ঈশ্বর দাবি করেছেন এবং আশ্বস্ত করেছেন যে এই শয়তান ব্যর্থ হয়েছে এবং সে যা করেছে তা করতে ব্যর্থ হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَيَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَجَّ هَذَا ‏ ‏الْبَيْتَ ‏ ‏فَلَمْ ‏ ‏يَرْفُثْ ‏ ‏وَلَمْ يَفْسُقْ رَجَعَ كَمَا وَلَدَتْهُ أُمُّهُ ‏","","",""],[8946,8946,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের কাছে ঈশ্বরের ঋণের একটা খেলনা নিয়ে এসেছে, তোমার টাকা আমার বাবার জন্য দেয়া হয়েছে, ঈশ্বরের দোহাইর কাছে","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ عَلَى غُلَامِ الْمُسْلِمِ وَلَا عَلَى فَرَسِهِ ‏ ‏صَدَقَةٌ ‏","","",""],[8947,8947,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমার বন্য পুত্র নিয়ে আমরা দাঙ্গা করেছি। আমার বাবার সাথে, আমার কানের মহিমায় ঘোড়ার সাথে যাও, আর আমি একজনকে খুন করবো। মসজিদ, বাবা তার জন্য প্রার্থনা এবং সেখানে পৌঁছে","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ الْمُهَاجِرِ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ الْمُحَارِبِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا قُعُودًا مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فِي الْمَسْجِدِ ‏ ‏فَأَذَّنَ الْمُؤَذِّنُ فَقَامَ رَجُلٌ فِي الْمَسْجِدِ فَخَرَجَ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَمَّا هَذَا فَقَدْ عَصَى ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[8948,8948,"","আমরা একটি আবেগ কথা বলেছি যা আমার বাবার জন্য একটা হৃদয় বয়ে এনেছে, একটা ব্যাতিক্রমের কথা শুনেছি। সে তার জন্য প্রার্থনা করেছিল এবং তাকে জিজ্ঞেস করলো যে, সে আমাকে ঘুমের মধ্যে দেখে নি। মনে হচ্ছে আমি আর যে মিথ্যা বলেছে সে ইচ্ছা করে তার পেট থেকে পড়ে গেছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ذَكْوَانَ أَبَا صَالِحٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي إِنَّ الشَّيْطَانَ لَا يَتَصَوَّرُ بِي ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ لَا يَتَشَبَّهُ بِي ‏ ‏وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[8949,8949,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি যা আমাদের বাবার জন্মের ব্যাপারে সমস্যার সৃষ্টি করেছে। তার বাবা, তার ছেলে এবং তার বাবা তার ছেলে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُلُّ مَوْلُودٍ يُولَدُ عَلَى ‏ ‏الْفِطْرَةِ ‏ ‏فَأَبَوَاهُ يُهَوِّدَانِهِ وَيُنَصِّرَانِهِ وَيُشْرِكَانِهِ ‏","","",""],[8950,8950,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি, যা আমাদের বাবার মঙ্গলের জন্য একটা অনুভূতি এনে দিয়েছে। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি আপনার জন্য ভাল কিছু বলবেন এবং তিনি আমাকে বলবেন যে তিনি আমাকে বলেছেন। সে হবে সেই ব্যক্তি যে বলবে যে বলবে যে তাকে হতে হবে সে হবে সেই ব্যক্তি, যে হবে সেই হবে সেই ব্যক্তি, যে হবে সেই ব্যক্তি, যে হবে সেই ব্যক্তি । সে-ই হবে সেই লোক যে হবে সেই ব্যক্তি যে একজন হবে সে-ই হতে পারে সে-ই হবে সেই ব্যক্তি যে হবে হবে, সে হবে একজন যে হবে হবে সেই হবে, সে হবে একজন যে হবে। সে-ই হবে সেই লোক যে একজন হবে, সে হবে সেই ব্যক্তি যে হবে । সেই ব্যক্তি হবেন সেই ব্যক্তি যে কিনা হবে সেই ব্যক্তি, যিনি একজন পুরুষ হবেন। যে একজন হবে সেই হবে যে কিনা হবে এক যে একবার বা দু'বার, তারপর তাদের পা থেকে বিষের মত মুছে ফেলা হবে, মৃত্যু।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَيْرُكُمْ ‏ ‏قَرْنِي ‏ ‏ثُمَّ الَّذِينَ يَلُونَهُمْ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لَا أَدْرِي ذَكَرَ مَرَّتَيْنِ أَوْ ثَلَاثًا ‏ ‏ثُمَّ خَلَفَ مِنْ بَعْدِهِمْ قَوْمٌ يُحِبُّونَ السِّمَانَةَ يَشْهَدُونَ وَلَا يُسْتَشْهَدُونَ ‏","","",""],[8951,8951,"","আমরা একটা আবেগ মুক্ত করতে চেষ্টা করেছি... ...যেটা আমি আমার বাবার খুশি খুশি খুশির কথা শুনেছি, সে তার জন্য প্রার্থনা করেছিল আর সে আত্মসমর্পণ করেছিল আমি আমার আগুনের কথা জিজ্ঞেস করি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ أَبِي سَعِيدٍ الْمَقْبُرِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَسْفَلَ مِنْ الْكَعْبَيْنِ فَفِي النَّارِ ‏ ‏يَعْنِي ‏ ‏الْإِزَارَ ‏","","",""],[8952,8952,"","আমরা এমন আবেগ নিয়ে কথা বলেছি যা আপনাকে নিয়ে এসেছে যারা আপনার বিরুদ্ধে পাপ করেছে। সে ঈশ্বরের কাছে প্রার্থনা করেছে এবং বলবে সে তার সর্বোচ্চ চেষ্টা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَفْلَسَ رَجُلٌ بِمَالِ قَوْمٍ فَرَأَى رَجُلٌ مَتَاعَهُ بِعَيْنِهِ فَهُوَ أَحَقُّ بِهِ مِنْ غَيْرِهِ ‏","","",""],[8953,8953,"","আমরা একটি আবেগ কথা বলেছি যে আমরা আনন্দের ফুলকে বলতে পারি... ...তিনি ঈশ্বরের কাছে প্রার্থনা করেন... ...এবং তার জন্য প্রার্থনা করেন এবং দর্শক এবং স্টান্টের পঞ্চম ছায়ার জন্য এই স্টান্ট আর আত্মার চমক, মদ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسٌ مِنْ الْفِطْرَةِ ‏ ‏الْخِتَانُ ‏ ‏وَالِاسْتِحْدَادُ ‏ ‏وَنَتْفُ الْإِبْطِ وَتَقْلِيمُ الْأَظْفَارِ وَقَصُّ الشَّارِبِ ‏","","",""],[8954,8954,"","আমরা একটি আবেগ কথা বলেছি যা আমাদের হৃদয়ের জন্য আমার আত্মাকে উপহার হিসেবে নিয়ে এসেছে। ঈশ্বর তাঁর দশম আদর্শ এবং আমার নীরবতার বছর পালন করতে হবে। আর আমি তাকে বিভ্রান্ত করব.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ الْقُرْدُوسِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا وَالصَّوْمُ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ يَدَعُ طَعَامَهُ وَشَرَابَهُ مِنْ ‏ ‏جَرَّايَ ‏ ‏الصَّوْمُ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ عِنْدَ اللَّهِ عَزَّ وَجَلَّ أَطْيَبُ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[8955,8955,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা বলে যে, আমরা আমার বাবার চেয়ে ভালো আছি। সে তোমাকে জীবন দিতে চায়, যে ছেলে একটা চমক নয়। অন্ত্যেষ্টিক্রিয়ার আয়োজন করে যুদ্ধ শুরু করে অথবা সেখানে গিয়ে দেখা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُوشِكُ مَنْ عَاشَ مِنْكُمْ أَنْ يَلْقَى ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏إِمَامًا مَهْدِيًّا وَحَكَمًا عَدْلًا فَيَكْسِرُ الصَّلِيبَ وَيَقْتُلُ الْخِنْزِيرَ وَيَضَعُ ‏ ‏الْجِزْيَةَ ‏ ‏وَتَضَعُ الْحَرْبُ ‏ ‏أَوْزَارَهَا ‏","","",""],[8956,8956,"","আমি আমার বাবার প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি, যে কিনা তার জন্য প্রার্থনা করেছে, আমি তাকে বলেছি যে আমাকে ঘুমের মধ্যে দেখে সে আমাকে দেখে নিল যখন আমাকে দেখে তখন সে আমাকে দেখে নি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فَإِنَّ الشَّيْطَانَ لَا يَتَمَثَّلُ بِي ‏","","",""],[8957,8957,"","আমি আমার বাবার প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি, আমার সন্তানদের এক মরুভূমি, আমি বলছি যে তারা এক বছর ধরে এটা লিখেছে, এটা করার জন্য সে এক ভাল বছর লিখিত আছে, যদি না সে তা করে থাকে, সে এটা করেনি, এক ভাল বছর ছিল আর তারা তা করেনি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةٌ فَإِنْ عَمِلَهَا كُتِبَتْ لَهُ عَشْرُ أَمْثَالِهَا إِلَى سَبْعِ مِائَةٍ وَسَبْعِ أَمْثَالِهَا فَإِنْ لَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةٌ وَمَنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا لَمْ تُكْتَبْ عَلَيْهِ ‏","","",""],[8958,8958,"","আমরা আমার ভাই হওয়া একজন উৎপীড়ক হওয়া সম্পর্কে কথা বলেছি যে কি ঘটেছে ভয় পেতে. আমি তাকে টিকাের ছেলেকে দিচ্ছি তুমি যাবে আর তার ছেলেকে তার ছেলেকে তার কাছে রেখে দেবে আমাকে যেতে হবে, ঈশ্বরের মাথা নষ্ট হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏الْفَأْرَةُ مِمَّا مُسِخَ ‏ ‏وَآيَةُ ‏ ‏ذَلِكَ أَنَّهُ يُوضَعُ لَهَا لَبَنُ ‏ ‏اللِّقَاحِ ‏ ‏فَلَا تَقْرَبُهُ وَإِذَا وُضِعَ لَهَا لَبَنُ الْغَنَمِ أَصَابَتْ مِنْهُ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏كَعْبٌ ‏ ‏سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَأُنْزِلَتْ عَلَيَّ التَّوْرَاةُ ‏","","",""],[8959,8959,"","আমি বলছি যে ব্রাহ্মাকে মেরে ফেলবে এবং ভালো হবে পঞ্চম ঊর্ধ্বমুখী কাঠামোয়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْبَهِيمَةُ ‏ ‏عَقْلُهَا ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[8960,8960,"","আমরা আমার বাবার একটা খেলনা নিয়ে কথা বলেছি, তারপর শুনেছি অথবা শুনেছি, একটি ঘোড়া তার কাছে প্রার্থনা করছে এবং প্রার্থনা করছে, এবং প্রার্থনা করছে, তারা ভাল আছে এবং এটা মূল্য.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤَذِّنُ يُغْفَرُ لَهُ ‏ ‏مَدَّ ‏ ‏صَوْتِهِ وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ وَشَاهِدُ الصَّلَاةِ يُكْتَبُ لَهُ خَمْسٌ وَعِشْرُونَ حَسَنَةً وَيُكَفَّرُ عَنْهُ مَا بَيْنَهُمَا ‏","","",""],[8961,8961,"","ঈশ্বর তাকে আদেশ দিয়েছেন যেন তিনি তা না করেন এবং আত্মসমর্পণ না করেন । তারা গ্রেসের কাছে ফিরে গিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا الْإِمَامُ ‏ ‏لِيُؤْتَمَّ ‏ ‏بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا لَكَ الْحَمْدُ وَإِنْ صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ ‏","","",""],[8962,8962,"","আমরা আমাদের সময়ের প্রতি প্রবল আগ্রহ, আমার বাবার সুখী ছেলে, কিন্তু আমার বাবার একটা মেয়ে আছে, যে আমার বাবার কাছে একটা আশীর্বাদের উপহার দিয়েছে, যে সব প্রার্থনায় আমাকে বলল যে তিনি যেন আমাকে সাহায্য করেন। তার নামে পড়, আমি তোমার কথা শুনছি আর তোমাকে আমার লুকানোর দরকার আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُحَمَّدٍ أَظُنُّهُ حَبِيبُ بْنُ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏فِي كُلِّ الصَّلَوَاتِ يَقْرَأُ فِيهَا ‏ ‏فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا أَخْفَى عَلَيْنَا أَخْفَيْنَا عَلَيْكُمْ ‏","","",""],[8963,8963,"","আমি তাদের সঙ্গে কথা বলেছিলাম, দয়া করে আমাকে এটা করতে হবে বলে আমি কথা বলেছিলাম । আর মুখটা দেখে দেখো, নাইলে মিথ্যা বলে ফেল।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَيْنَانِ تَزْنِيَانِ وَاللِّسَانُ يَزْنِي وَالْيَدَانِ تَزْنِيَانِ وَالرِّجْلَانِ تَزْنِيَانِ وَيُحَقِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ الْفَرْجُ ‏","","",""],[8964,8964,"","ঈশ্বরের কাছে প্রার্থনা করার সময় প্রভু এমন দুজন ব্যক্তিকে আত্মসমর্পণ করবেন, যারা হয়তো তাকে হত্যা করেছে । তারা বলেছিল যে, ঈশ্বর অনেক বেশি ছিলেন আর এরপর তিনি বলেছিলেন যে, তারা অন্যদের ক্ষমা করে দেয় ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسِيرُ فِي طَرِيقِ ‏ ‏مَكَّةَ ‏ ‏فَأَتَى عَلَى ‏ ‏جُمْدَانَ ‏ ‏فَقَالَ هَذَا ‏ ‏جُمْدَانُ ‏ ‏سِيرُوا سَبَقَ ‏ ‏الْمُفَرِّدُونَ ‏ ‏قَالُوا وَمَا الْمُفَرِّدُونَ قَالَ الذَّاكِرُونَ اللَّهَ كَثِيرًا ثُمَّ قَالَ اللَّهُمَّ اغْفَرْ لِلْمُحَلِّقِينَ قَالُوا وَالْمُقَصِّرِينَ قَالَ ‏ ‏اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ قَالُوا وَالْمُقَصِّرِينَ قَالَ وَالْمُقَصِّرِينَ ‏","","",""],[8965,8965,"","আর এই নামই ভগবানকে বলে, এটা করতে আর ঈশ্বরের কাছে আত্মসমর্পণ করতে বলা।","‏ ‏وَبِهَذَا الْإِسْنَادِ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتُؤَدُّنَّ الْحُقُوقَ إِلَى أَهْلِهَا حَتَّى ‏ ‏يُقَادَ ‏ ‏لِلشَّاةِ ‏ ‏الْجَلْحَاءِ ‏ ‏مِنْ الشَّاةِ ‏ ‏الْقَرْنَاءِ ‏","","",""],[8966,8966,"","আর ঈশ্বরের দোহাই তাকে আত্মসমর্পণ করতে আদেশ দিয়েছে... ...সে বলছে সে তার নামও বিষ দেবে না, তার বাগদত্তা তার বাগ্‌দত্তা ইচ্ছার কথা","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏يَسُومُ ‏ ‏الرَّجُلُ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ الْمُسْلِمِ وَلَا يَخْطُبُ عَلَى خِطْبَتِهِ ‏","","",""],[8967,8967,"","( খ) কেন আমরা বলতে পারি যে, যিহোবা আমাদের জন্য চিন্তা করেন?","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ هَذَا الْحَرَّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ ‏","","",""],[8968,8968,"","আর এই শিকারী সৃষ্টিকর্তাকে জিজ্ঞেস করতে বলেছে যে, সে তাকে ত্যাগ করেছে এবং শয়তান তাকে মুক্ত করেছে।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَمِعَ الشَّيْطَانُ الْأَذَانَ ‏ ‏وَلَّى ‏ ‏وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ الصَّوْتَ ‏","","",""],[8969,8969,"","আর শিকারী বলেছে, ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন। আমি পুরো শব্দ দিয়েছি, আর আমি ভদ্র ও ভদ্র গান গাওয়াতে ক্লান্ত। আমার মত নবীরা শুধু প্রার্থনা করে আর স্পর্শ করে, আমি কোন মেয়েকে আমার সবচেয়ে ভালো ছেলেকেও হারাতে দেখছি না।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُضِّلْتُ عَلَى الْأَنْبِيَاءِ بِسِتٍّ قِيلَ مَا هُنَّ أَيْ رَسُولَ اللَّهِ قَالَ ‏ ‏أُعْطِيتُ ‏ ‏جَوَامِعَ الْكَلِمِ ‏ ‏وَنُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏وَأُحِلَّتْ لِي الْغَنَائِمُ وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا وَأُرْسِلْتُ إِلَى الْخَلْقِ كَافَّةً وَخُتِمَ ‏ ‏بِيَ النَّبِيُّونَ مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ عَلَيْهِمْ الصَّلَاةُ وَالسَّلَامُ كَمَثَلِ رَجُلٍ بَنَى قَصْرًا فَأَكْمَلَ بِنَاءَهُ وَأَحْسَنَ بُنْيَانَهُ إِلَّا مَوْضِعَ ‏ ‏لَبِنَةٍ ‏ ‏فَنَظَرَ النَّاسُ إِلَى الْقَصْرِ فَقَالُوا مَا أَحْسَنَ بُنْيَانَ هَذَا الْقَصْرِ لَوْ تَمَّتْ هَذِهِ ‏ ‏اللَّبِنَةُ ‏ ‏أَلَا فَكُنْتُ أَنَا ‏ ‏اللَّبِنَةَ ‏ ‏أَلَا فَكُنْتُ أَنَا ‏ ‏اللَّبِنَةَ ‏","","",""],[8970,8970,"","আমি আমার বাবার সঙ্গে একজন দেবতা হওয়ার বিষয়ে কথা বলেছিলাম । জঘন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْبَرِي عَلَى تُرْعَةٍ مِنْ ‏ ‏تُرَعِ ‏ ‏الْجَنَّةِ وَمَا بَيْنَ مِنْبَرِي وَحُجْرَتِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ ‏","","",""],[8971,8971,"","বেনের প্রতি করুণা দেখানোর কথা আমরা কথা বলেছি যখন আমরা আলোচনা করেছিলাম তিনি কি ভাল করেছেন। আমি আল্লাহ এটা করেছেন এবং আমি বলবো আল্লাহ আমার টাকা আছে এবং তার আরও তিনজন আছে টাকা, নাহলে আমি নিজেই বলব তুমি কী করবে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَقُولُ الْعَبْدُ مَالِي وَإِنَّ مَا لَهُ مِنْ مَالِهِ ثَلَاثٌ مَا أَكَلَ فَأَفْنَى أَوْ لَبِسَ فَأَبْلَى أَوْ أَعْطَى فَأَقْنَى مَا سِوَى ذَلِكَ ذَاهِبٌ وَتَارِكُهُ لِلنَّاسِ ‏","","",""],[8972,8972,"","আর শিকারী বলেছে যে ঈশ্বর তাকে আদেশ দিয়েছেন আর তাকে মনে রাখার জন্য রাজি না হয়.","‏ ‏وَبِهَذَا الْإِسْنَادِ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَنْذِرُوا ‏ ‏فَإِنَّ ‏ ‏النَّذْرَ ‏ ‏لَا يُقَدِّمُ مِنْ ‏ ‏الْقَدَرِ ‏ ‏شَيْئًا وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنْ الْبَخِيلِ ‏","","",""],[8973,8973,"","আমার বাবা এমন একটা উপহার, যা ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর ইচ্ছা পালন করার অধিকার দিয়েছেন । ( মথি ৫: ৩, ৪) এভাবে, তিনি তার পাপ ক্ষমা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ الْقَاصُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ سِتٌّ قَالُوا وَمَا هُنَّ يَا رَسُولَ اللَّهِ قَالَ إِذَا لَقِيتَهُ سَلِّمْ عَلَيْهِ وَإِذَا دَعَاكَ فَأَجِبْهُ وَإِذَا اسْتَنْصَحَكَ فَانْصَحْ لَهُ وَإِذَا عَطَسَ فَحَمِدَ اللَّهَ ‏ ‏فَشَمِّتْهُ ‏ ‏وَإِذَا مَرِضَ ‏ ‏فَعُدْهُ ‏ ‏وَإِذَا مَاتَ فَاصْحَبْهُ ‏","","",""],[8974,8974,"","আর এই শিকারী সৃষ্টিকর্তাকে জিজ্ঞেস করতে বলেছে যে, তার কাছে প্রার্থনা করা হয়েছে এবং সে কতটা লড়াই করেছে তা শুনবে না।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَجْتَمِعُ كَافِرٌ وَقَاتِلُهُ مِنْ الْمُسْلِمِينَ فِي النَّارِ أَبَدًا ‏","","",""],[8975,8975,"","আর এই শিকারী বলেছিল যে খোদা তার জন্য প্রার্থনা করে... ...আর ঈশ্বর বলে যে ঈশ্বর আমার দেবতা, তারা আমাকে কেটে ফেলবে আর তাদের স্বপ্ন আমাকে মেরে ফেলবে. তাদের ধরে রেখে আর তোমাকে ঈশ্বরের কাছে যেতে হবে না, তারা তোমার কাছে ফিরে আসবে না।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ لِي قَرَابَةً أَصِلُهُمْ وَيَقْطَعُونِي وَأَحْلُمُ عَنْهُمْ فَيَجْهَلُونَ عَلَيَّ وَأُحْسِنُ إِلَيْهِمْ وَيُسِيئُونَ إِلَيَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَ كَمَا تَقُولُ لَكَأَنَّمَا ‏ ‏تُسِفُّهُمْ ‏ ‏الْمَلَّ ‏ ‏وَلَا يَزَالُ مَعَكَ مِنْ اللَّهِ ظَهِيرٌ عَلَيْهِمْ مَادُمْتَ عَلَى ذَلِكَ ‏","","",""],[8976,8976,"","আমরা শেষবারের মতো বলেছিলাম যে আমরা যেতে চাই, সে বলল আমরা কেন ঈশ্বরের দোহাই দিয়ে যাই আর তাকে সেটা উদ্ধার করতে হবে। আমি শপথ করে বলছি, আল্লাহকে মূল্যবান মনে করি। আমি নিশ্চিত করছি, এটা ঈশ্বরের কাছে মূল্যবান। আমি যদি এটা করতে চাই, আমি এটা করতে চাই, আমি এটা করতে চাই। আমি জানি, আমি কি সত্যিই জানি যে, আমি এটা করতে পারি। আমি জানি না যে, আমি এটা করতে পারি, আমি কি বলছি, আমি জানি, আমি এটা করতে পারি। আমি জানি না যে, আমি যদি আমার সিদ্ধান্ত নেই, আমি এটা করতে চাই, আমি এটা করতে চাই, আমি শুধু একটা ছোট কাজ করি। আমি যদি চাই, আমি এটা করি, আমি জানি। আমি জানি, আমি জানি যে, আমি জানি যে, আমি এটা করতে চাই, আমি জানি না। আমি জানি যে, আমি এটা করি, আমি এটা আমার জন্য অনেক কিছু করতে হবে। কিন্তু আমি কি করবো। আমি জানি না। আমি জানি না। আমি যদি তুমি এটা আমার কাছে এটা একটা প্রশ্ন করি, আমি যদি তুমি জানো, আমি এটা করতে পারি। কিন্তু আমি এখন আমি এটা করতে পারি। আমি এটা করতে পারি। আমি এটা করতে পারি। কিন্তু আমি যখন তুমি এটা আমার কাছে এটা করতে পারি, আমি এটা আমার কাছে এটা একটা প্রশ্ন করি। কিন্তু আমি যখন তুমি জানো, আমি এটা আমার কাছে এটা ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং ঈশ্বরের কাছে নিজেকে সমর্পণ করেছেন আর এরপর তারা ঈশ্বরের কাছে এসে পৌঁছেছেন । তার কাছে প্রার্থনা করো আর আমি বলতে চাই সে তোমার লেখা কীভাবে লিখেছে, কিন্তু আমি তোমাকে ক্ষমা করতে পেরেছি, কিন্তু আমাকে যেতে হবে না, আমাকে যেতে হবে এবং আমার মতো করে করতে হবে। আশা করি, তার বই আমাদের নির্দেশনা দেয়, আমরা তার একজন ঊর্ধ্বতন কর্মকর্তাকে ভেঙ্গে ফেলি না, তোমার জন্য ক্ষমা আমাদের ব্যবহার করতে হবে। আমরা যা করেছি তার জন্য আমাদের ভুল করতে হবে অথবা ভুল করতে হবে, আমরা তাকে না ধরে ছিলাম গুহার পা","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الْأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏} ‏فَاشْتَدَّ ذَلِكَ عَلَى صَحَابَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏جَثَوْا ‏ ‏عَلَى الرُّكَبِ فَقَالُوا يَا رَسُولَ اللَّهِ كُلِّفْنَا مِنْ الْأَعْمَالِ مَا نُطِيقُ الصَّلَاةَ وَالصِّيَامَ وَالْجِهَادَ ‏ ‏وَالصَّدَقَةَ ‏ ‏وَقَدْ أُنْزِلَ عَلَيْكَ هَذِهِ الْآيَةُ وَلَا نُطِيقُهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُرِيدُونَ أَنْ تَقُولُوا كَمَا قَالَ أَهْلُ الْكِتَابَيْنِ مِنْ قَبْلِكُمْ سَمِعْنَا وَعَصَيْنَا بَلْ ‏ ‏قُولُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ فَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ فَلَمَّا أَقَرَّ بِهَا الْقَوْمُ وَذَلَّتْ بِهَا أَلْسِنَتُهُمْ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِي إِثْرِهَا ‏ { ‏آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ‏} ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَرَأَهَا ‏ ‏سَلَّامٌ أَبُو الْمُنْذِرِ ‏ ‏يُفَرِّقُ ‏ { ‏وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ‏} ‏فَلَمَّا فَعَلُوا ذَلِكَ ‏ ‏نَسَخَهَا ‏ ‏اللَّهُ تَبَارَكَ وَتَعَالَى بِقَوْلِهِ ‏ { ‏لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا ‏ ‏وُسْعَهَا ‏ ‏لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ‏} ‏فَصَارَ لَهُ مَا كَسَبَتْ مِنْ خَيْرٍ وَعَلَيْهِ مَا اكْتَسَبَتْ مِنْ شَرٍّ فَسَّرَ ‏ ‏الْعَلَاءُ ‏ ‏هَذَا ‏ { ‏رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ‏} ‏قَالَ نَعَمْ ‏ { ‏رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا ‏ ‏إِصْرًا ‏ ‏كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ‏} ‏قَالَ نَعَمْ ‏ { ‏رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ‏} ‏قَالَ نَعَمْ ‏ { ‏وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ‏}","","",""],[8977,8977,"","আমরা কি করতে পারি তা নিয়ে কথা বলছিলাম। আমার বাবা বলেছেন, \"ঈশ্বর এসে গেছেন\" তিনি বললেন, তিনি আমার বাবার কাছে ফোন রেখে থেকে আমাকে যেতে বাধা দিয়েছেন। আপনি আমাকে জিজ্ঞেস করতে চান আমি যদি ঈশ্বরকে জিজ্ঞাসা করি তাকে কথা বলতে বলুন। ঈশ্বর তাঁর কাছে ফোন করেছেন এবং আমি আপনাকে বলছি যে, আমি আপনাকে একটা গোপন বিষয় শিক্ষা দিতে পারি না এবং আপনাকে বলি যে, আপনি মঞ্চে না যান এবং ভেতরে না যান বেইজমেন্ট আর আমরা উৎসবে যাই না আর মুখে মুখে... ...ঈশ্বর তার জন্য প্রার্থনা করে... ...এবং আমি আত্মসমর্পণ করে যাচ্ছি যতক্ষণ না তুমি এটা করো, আমি তোমাকে এই ভালবাসা থেকে মুক্ত করে দেব না। আমার হাত দিয়ে আমার কথা বলা উচিত এবং ভুল কিছু করার আগে আমি ভুল কিছু করার আগে আমাকে বলা ঠিক করে দিতে হবে। সে আমাকে জিজ্ঞেস করে যে সে কিভাবে প্রার্থনা করার সিদ্ধান্ত নিয়েছে। ঈশ্বর আমার ছেলেকে উদ্ধার করেছেন, যিনি আমার ছেলেকে কখনো হারতে দেননি। ঈশ্বরের প্রতি ভালবাসা, সে আমার শিং বিক্রি করে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَقَالَ يَا ‏ ‏أُبَيُّ ‏ ‏فَالْتَفَتَ فَلَمْ يُجِبْهُ ثُمَّ صَلَّى ‏ ‏أُبَيٌّ ‏ ‏فَخَفَّفَ ثُمَّ انْصَرَفَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ السَّلَامُ عَلَيْكَ أَيْ رَسُولَ اللَّهِ قَالَ وَعَلَيْكَ قَالَ مَا مَنَعَكَ أَيْ ‏ ‏أُبَيُّ ‏ ‏إِذْ دَعَوْتُكَ أَنْ تُجِيبَنِي قَالَ أَيْ رَسُولَ اللَّهِ كُنْتُ فِي الصَّلَاةِ قَالَ أَفَلَسْتَ تَجِدُ فِيمَا أَوْحَى اللَّهُ إِلَيَّ أَنْ ‏ { ‏اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ ‏} ‏قَالَ قَالَ بَلَى أَيْ رَسُولَ اللَّهِ لَا أَعُودُ قَالَ أَتُحِبُّ أَنْ أُعَلِّمَكَ سُورَةً لَمْ تَنْزِلْ فِي التَّوْرَاةِ وَلَا فِي الزَّبُورِ وَلَا فِي الْإِنْجِيلِ وَلَا فِي الْفُرْقَانِ مِثْلُهَا قَالَ قُلْتُ نَعَمْ أَيْ رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَرْجُو أَنْ لَا تَخْرُجَ مِنْ هَذَا الْبَابِ حَتَّى تَعْلَمَهَا قَالَ فَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِي يُحَدِّثُنِي وَأَنَا أَتَبَطَّأُ مَخَافَةَ أَنْ يَبْلُغَ قَبْلَ أَنْ ‏ ‏يَقْضِيَ ‏ ‏الْحَدِيثَ فَلَمَّا أَنْ ‏ ‏دَنَوْنَا ‏ ‏مِنْ الْبَابِ قُلْتُ أَيْ رَسُولَ اللَّهِ مَا السُّورَةُ الَّتِي وَعَدْتَنِي قَالَ فَكَيْفَ تَقْرَأُ فِي الصَّلَاةِ قَالَ فَقَرَأْتُ عَلَيْهِ ‏ ‏أُمَّ الْقُرْآنِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ مَا أَنْزَلَ اللَّهُ فِي التَّوْرَاةِ وَلَا فِي الْإِنْجِيلِ وَلَا فِي الزَّبُورِ وَلَا فِي الْفُرْقَانِ مِثْلَهَا وَإِنَّهَا ‏ ‏لَلسَّبْعُ مِنْ الْمَثَانِي ‏","","",""],[8978,8978,"","একটা স্যুটের মধ্যে একটা ঘোড়ার জন্ম হয়, যা ঈশ্বর এই সমস্তকিছু বলেছিলেন । দূর হ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏أَنَّ فَتًى مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَتَى ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَتَبَخْتَرُ فِي حُلَّةٍ لَهُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَجُلًا مِمَّنْ كَانَ قَبْلَكُمْ كَانَ ‏ ‏يَتَبَخْتَرُ ‏ ‏فِي حُلَّةٍ لَهُ قَدْ أَعْجَبَتْهُ ‏ ‏جُمَّتُهُ ‏ ‏وَبُرْدَاهُ ‏ ‏إِذْ ‏ ‏خُسِفَ ‏ ‏بِهِ الْأَرْضُ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏فِيهَا حَتَّى تَقُومَ السَّاعَةُ ‏","","",""],[8979,8979,"","আমার বাবা একজন পলাতক ব্যক্তি আর তিনি তার বাবার জ্যোতিতে বসে আছেন । ভয়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَفْلَسَ الرَّجُلُ ‏ ‏فَالْغَرِيمُ ‏ ‏أَحَقُّ بِمَتَاعِهِ إِذَا وَجَدَهُ بِعَيْنِهِ ‏","","",""],[8980,8980,"","আমি আমার বাবার সাথে কথা বলেছিলাম যে সে আমাকে খুন করবে। সে আমাকে খুন করবে বলে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَرَأَ ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَسَجَدَ قُلْتُ لِمَ أَرَاكَ سَجَدْتَ فِيهَا قَالَ لَوْ لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِيهَا مَا سَجَدْتُ ‏","","",""],[8981,8981,"","আমরা কথা বলেছিলাম আমরা কতটা ভালো আছি, ঈশ্বরের দোহাইের সাথে তার সম্পর্ক আছে আর সে এটা বলতে পারবে যে বসে শুয়ে শুয়ে শুয়ে পড়া উচিত।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْيَمِينُ ‏ ‏الْكَاذِبَةُ ‏ ‏مَنْفَقَةٌ ‏ ‏لِلسِّلْعَةِ ‏ ‏مَمْحَقَةٌ ‏ ‏لِلْكَسْبِ ‏","","",""],[8982,8982,"","আমরা শেষবারের মতো কথা বলেছি, আমি আসলে একটা ছেলে যে এ ব্যাপারে কথা বলছিলাম, যে কিনা এ ব্যাপারে ছিল। অথবা বিড়ালেরা বলবে চুপ থাকা। ঈশ্বর ভাল আছেন, আমার একটা মিথ্যার শিকার হওয়াটা ইচ্ছা করেই শুরু করার জন্য তৈরি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي ابْنَ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ كُلَيْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏وَكَانَ يَبْتَدِئُ حَدِيثَهُ بِأَنْ يَقُولَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏الصَّادِقُ الْمَصْدُوقُ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[8983,8983,"","আমরা এক কথা বলেছি যে আমরা চিন্তা করার চেয়ে ভাল কিছু করেছি। তিনি বললেন, ঈশ্বর তাকে উদ্ধার করতে হবে এবং ঈশ্বর আমাদের উদ্ধার করতে হবে। আমাকে বল শ্বাস নিতে। মন থেকে মনে রাখবে, আমার মুখে তুমি কে হতে পারবে?","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو صَالِحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ حِينَ يَذْكُرُنِي إِنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي وَإِنْ ذَكَرَنِي فِي مَلَإٍ ذَكَرْتُهُ فِي مَلَإٍ خَيْرٍ مِنْهُ وَمَنْ تَقَرَّبَ إِلَيَّ شِبْرًا تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا وَمَنْ تَقَرَّبَ إِلَيَّ ذِرَاعًا تَقَرَّبْتُ إِلَيْهِ ‏ ‏بَاعًا ‏ ‏وَمَنْ جَاءَنِي يَمْشِي جِئْتُهُ مُهَرْوِلًا ‏","","",""],[8984,8984,"","তিনি শান্তি বজায় রেখেছিলেন এবং আমার জন্য তিনি স্থির করেছিলেন যে, যে - ব্যক্তি এটা করতে চেয়েছিল, তিনি আমাকে ভালোবাসেন । যে তাকে ভালো পছন্দ করে আর তারপর ঈশ্বরের অনুগ্রহে আমাকে ডাকতে পছন্দ করে, তারপর আমি তাকে চুমু দেই এবং ঈশ্বর তাকে কিছু সুযোগ করে দেয়, সে এটা বন্ধ করে দেয়, আর তারপর সে এটাকে গাধা বলে, তারপর তুমি তাকে ভেড়ার মাংসের উপর পেশাব করার জন্য রেখে দিলে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا أَحَبَّ عَبْدًا دَعَا ‏ ‏جِبْرِيلَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏يَا ‏ ‏جِبْرِيلُ ‏ ‏إِنِّي أُحِبُّ فُلَانًا فَأَحِبَّهُ قَالَ فَيُحِبُّهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ ثُمَّ يُنَادِي فِي أَهْلِ السَّمَاءِ إِنَّ اللَّهَ يُحِبُّ فُلَانًا قَالَ فَيُحِبُّهُ أَهْلُ السَّمَاءِ ثُمَّ يُوضَعُ لَهُ الْقَبُولُ فِي الْأَرْضِ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا أَبْغَضَ عَبْدًا دَعَا ‏ ‏جِبْرِيلَ ‏ ‏فَقَالَ يَا ‏ ‏جِبْرِيلُ ‏ ‏إِنِّي أُبْغِضُ فُلَانًا فَأَبْغِضْهُ قَالَ فَيُبْغِضُهُ ‏ ‏جِبْرِيلُ ‏ ‏ثُمَّ يُنَادِي فِي أَهْلِ السَّمَاءِ إِنَّ اللَّهَ يُبْغِضُ فُلَانًا فَأَبْغِضُوهُ قَالَ فَيُبْغِضُهُ أَهْلُ السَّمَاءِ ثُمَّ تُوضَعُ لَهُ الْبَغْضَاءُ فِي الْأَرْضِ ‏","","",""],[8985,8985,"","আমরা আমার বাবা একজন পলাতক হিসেবে কথা বলেছি যে তুমি রাবার নিয়ে আসোনি... ...আর আমি এমন একজনের কাছ থেকে বল না পড়ি যখন ঈশ্বর ঈশ্বরের কাছে প্রার্থনা করে আর আমি স্বপ্ন দেখছি না। প্রভু উপস্থিতিতে এবং সম্মানের সাথে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَا احْتَذَى النِّعَالَ وَلَا انْتَعَلَ وَلَا رَكِبَ ‏ ‏الْمَطَايَا ‏ ‏وَلَا لَبِسَ ‏ ‏الْكُورَ ‏ ‏مِنْ رَجُلٍ بَعْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ مِنْ ‏ ‏جَعْفَرِ بْنِ أَبِي طَالِبٍ ‏ ‏يَعْنِي فِي ‏ ‏الْجُودِ ‏ ‏وَالْكَرَمِ ‏","","",""],[8986,8986,"","তিনি সেইসমস্ত মিথ্যা ভাল্লুক ও মিথ্যা মালাদি ও শপথের শেষ করেছিলেন । আর প্রতিবেশী বা পরাজিত ব্যক্তি এক চূড়ান্ত সন্দেহের বিষয় ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ سِيرِينَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏أَمَّا أَحَدُهُمَا فَأَلْجَأَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَّا الْآخَرُ فَأَلْجَأَهُ إِلَى ‏ ‏عُمَرَ ‏ ‏قَالَ أَحَدُهُمَا ‏ ‏نَهَى عَنْ ‏ ‏الزِّقَاقِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَعَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَقَالَ الْآخَرُ نَهَى عَنْ ‏ ‏الزِّقَاقِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَعَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْجَرِّ ‏ ‏أَوْ الْفَخَّارِ شَكَّ ‏ ‏مُحَمَّدٌ ‏","","",""],[8987,8987,"","আমি আমার বাবার কথা বলেছিলাম, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তার প্রার্থনা শুনে সে আত্মসমর্পণ করবে যদি আমি তোমাকে তার প্রার্থনায় প্রার্থনা করি, সে কোন শব্দও শুনতে পাবে না অথবা কোন শব্দ শুনতে পাবে না। বাতাস.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَجَدَ أَحَدُكُمْ فِي صَلَاتِهِ حَرَكَةً فِي دُبُرِهِ ‏ ‏فَأَشْكَلَ ‏ ‏عَلَيْهِ ‏ ‏أَحْدَثَ ‏ ‏أَوْ لَمْ ‏ ‏يُحْدِثْ ‏ ‏فَلَا يَنْصَرِفْ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏","","",""],[8988,8988,"","আমি বাপ্তিস্ম নেওয়ার স্বপ্ন সম্বন্ধে বলেছিলাম যে, আমাদের এক উত্তম হাত ও এক স্বপ্ন রয়েছে । বইগুলো কেন চালায় নি?","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏وَصَالِحٌ الْمُعَلِّمُ ‏ ‏وَحُمَيْدٌ ‏ ‏وَيُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ مَا اجْتُنِبَتْ الْكَبَائِرُ ‏","","",""],[8989,8989,"","আমরা বাবার মৃত্যুর কথা বলেছিলাম, আমরা বাবার গডফাদারের ব্যাপারে কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর আশ্বস্ত করেছেন যে আমি আপনার জীবন নিয়ে নেবো। হে প্রভু ও প্রভুর অনুগ্রহ","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏فِتْنَةِ ‏ ‏الْمَحْيَا وَالْمَمَاتِ وَمِنْ شَرِّ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏","","",""],[8990,8990,"","তিনি কৌশলগুলো ও বসার ঘরের লোকেরা কপটতার সঙ্গে কথা বলার চেষ্টা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُخْتَلِعَاتُ ‏ ‏وَالْمُنْتَزِعَاتُ ‏ ‏هُنَّ الْمُنَافِقَاتُ ‏","","",""],[8991,8991,"","আমরা আমার ছেলেকে পাথর মারার চেষ্টা করার বিষয়ে বলেছিলাম যে অন্যায়ের জন্য মূল্য দিতে হবে । নেতৃত্ব, আগুনে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْكِي عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏الْكِبْرِيَاءُ رِدَائِي وَالْعَظَمَةُ ‏ ‏إِزَارِي ‏ ‏مَنْ نَازَعَنِي وَاحِدًا مِنْهُمَا قَذَفْتُهُ فِي النَّارِ ‏","","",""],[8992,8992,"","আমার বাবা আমাকে কিভাবে বলেছিলেন যে তিনি আমাকে খুন করতে যাচ্ছেন, নাকি সে একজন নারীকে ধ্বংস করে ফেলত, নাকি সে কোন মেয়েকে মেরে ফেলত। সে বলবে যে সে কিছু করেছে। তাদের নিজেদের সবচেয়ে অন্ধকার শক্তি ছিল.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ أَبِي فَاطَّلَعَ ‏ ‏أَبِي ‏ ‏فِي دَارِ قَوْمٍ فَرَأَى امْرَأَةً فَقَالَ أَمَا إِنَّهُمْ لَوْ فَقَئُوا عَيْنِي لَهُدِرَتْ ثُمَّ قَالَ حَدَّثَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اطَّلَعَ فِي دَارِ قَوْمٍ بِغَيْرِ إِذْنِهِمْ فَفَقَئُوا عَيْنَهُ هُدِرَتْ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً عَيْنٌ ‏","","",""],[8993,8993,"","আমার বাবা ঈশ্বরের দোহাই দিয়ে তার অধিকার স্বীকার করবেন না। বিশ্বাসের জীবন্ত.","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِيمَانُ بِضْعٌ وَسَبْعُونَ بَابًا أَفْضَلُهَا لَا إِلَهَ إِلَّا اللَّهُ ‏ ‏وَأَدْنَاهَا ‏ ‏إِمَاطَةُ ‏ ‏الْعَظْمِ عَنْ الطَّرِيقِ وَالْحَيَاءُ شُعْبَةٌ مِنْ الْإِيمَانِ ‏","","",""],[8994,8994,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার পেট থেকে আশীর্বাদের মতো না হয়ে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا جَرَسٌ ‏","","",""],[8995,8995,"","আমরা আমার ভালবাসার সাথে আমাকে সাহায্য করার কথা বলেছিলাম, নবী তার কাছে প্রার্থনা করেছিলেন, তিনি জানতেন যে আপনার লর্ড হয়তো ভালো থাকবে এবং বলবে, ছেলেটি আছে, যার সবার কাছেই। আমার কাছে অনেক অন্ধকার আছে আর আমি বধিরদের কাছে মাথা নত করি, সে রাজার অনুগ্রহ থেকে...","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ رَبَّكُمْ عَزَّ وَجَلَّ يَقُولُ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏بِكُلِّ حَسَنَةٍ عَشْرُ حَسَنَاتٍ إِلَى سَبْعِ مِائَةِ ضِعْفٍ إِلَى أَضْعَافٍ كَثِيرَةٍ وَالصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ وَالصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏مِنْ النَّارِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ عَزَّ وَجَلَّ مِنْ رِيحِ الْمِسْكِ فَإِنْ جَهِلَ عَلَى أَحَدِكُمْ جَاهِلٌ وَهُوَ صَائِمٌ فَلْيَقُلْ إِنِّي صَائِمٌ ‏","","",""],[8996,8996,"","বাবা যদি শোনেন, তাহলে তিনি একজন যাজকও । আমি তাকে তার নীতি বলতে চাই.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ سَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ ‏ ‏شِعْبَ ‏ ‏الْأَنْصَارِ ‏ ‏أَوْ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَمَا ظَلَمَ بِأَبِي وَأُمِّي ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَآوَوْهُ وَنَصَرُوهُ ‏ ‏قَالَ وَأَحْسَبُهُ قَالَ وَوَاسَوْهُ ‏","","",""],[8997,8997,"","আমরা তাকে থামাতে বলেছিলাম, ঈশ্বরের বাবা আমার কথা শুনে তাকে থামাতে চেষ্টা করার জন্য। ভবিষ্যদ্বাণীর জন্য তার কাছে প্রার্থনা করেছে এবং আমার মায়ের বক্তব্য তাকে দেবেনা। আমরা এমন একটা প্রান্তরে ধরা পড়েছিলাম, যা হয়তো তিনি করতে পারতেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏أَنْبَأَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا الرَّبِيعِ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْبَعٌ فِي أُمَّتِي لَنْ يَدَعُوهَا ‏ ‏التَّطَاعُنُ ‏ ‏فِي الْأَنْسَابِ ‏ ‏وَالنِّيَاحَةُ ‏ ‏وَمُطِرْنَا ‏ ‏بِنَوْءِ ‏ ‏كَذَا وَكَذَا اشْتَرَيْتَ بَعِيرًا أَجْرَبَ ‏ ‏أَوْ فَجَرِبَ ‏ ‏فَجَعَلْتَهُ فِي مِائَةِ بَعِيرٍ فَجَرِبَتْ مَنْ أَعْدَى الْأَوَّلَ ‏","","",""],[8998,8998,"","আমি তাকে বলতে চেয়েছিলাম, আমি তার কাছে সৌভাগ্যের কথা শুনেছি। আমি প্রভু তার জন্য প্রার্থনা করেন এবং তাকে আত্মসমর্পণ করি যখন তিনি বলেছিলেন তিনি মারা যান। আমি মনে করি তিনি বলেছিলেন, তিনি বলেছিলেন, আমি তাকে হত্যা করা হয়েছে। আমি জানি, আমি যদি আমার জীবনের জন্য প্রার্থনা করি, তাহলে আমি তাকে বলেছিলাম, আমি জানি, আমি যদি আমি আমার জীবনের জন্য প্রার্থনা করি, তাহলে আমি জানি, আমি জানি, আমি জানি, আমি যদি আমি সত্যিই তোমার কাছে ক্ষমা চাই, তাহলে আমি এটা একটা জিনিস আছে। আমি জানি, আমি জানি, আমি যদি আমি এটা একটা জিনিসকে বলি, তাহলে আমি তোমার কাছে ক্ষমা করতে পারি। আমি জানি, আমি জানি, আমি কি তাকে আমি তোমার কাছে ক্ষমা করতে পারি। আমি জানি না। আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, যদি সে তার প্রার্থনায় তোমাকে বিচার করতে চায়... ...তাহলে তার মুখ আর হারার সাথে প্রতারণা করা হবে না, তার প্রার্থনা নিজের হাতকে উড়িয়ে দিবে না, আর সে এটা করবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَاسِمُ بْنُ مِهْرَانَ ‏ ‏أَخْبَرَنِيهِ قَالَ سَمِعْتُ ‏ ‏أَبَا رَافِعٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي الْقِبْلَةِ ‏ ‏قَالَ كَانَ يَقُولُ مَرَّةً فَحَتَّهَا ‏ ‏قَالَ ثُمَّ قَالَ قُمْتُ ‏ ‏فَحَتَّيْتُهَا ثُمَّ قَالَ ‏ ‏أَيُحِبُّ أَحَدُكُمْ إِذَا كَانَ فِي صَلَاتِهِ أَنْ ‏ ‏يُتَنَخَّعَ ‏ ‏فِي وَجْهِهِ ‏ ‏أَوْ يُبْزَقَ فِي وَجْهِهِ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي صَلَاتِهِ فَلَا يَبْزُقَنَّ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلَكِنْ عَنْ يَسَارِهِ تَحْتَ قَدَمِهِ فَإِنْ لَمْ يَجِدْ قَالَ بِثَوْبِهِ هَكَذَا ‏","","",""],[8999,8999,"","আমি আমার বাবাকে একটা স্বপ্নের কথা বলেছিলাম । আর আরো একটা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُوشِكُ أَنْ ‏ ‏يَحْسِرَ ‏ ‏الْفُرَاتُ عَنْ جَبَلٍ مِنْ ذَهَبٍ فَيَقْتَتِلَ عَلَيْهِ النَّاسُ حَتَّى يُقْتَلَ مِنْ كُلِّ عَشَرَةٍ تِسْعَةٌ وَيَبْقَى وَاحِدٌ ‏","","",""],[9000,9000,"","আমরা একটা কুকুরের ছেলেের কথা বলেছিলাম যে কাজ করতে পারবে। সে ঈশ্বরের কাছে প্রার্থনা করেছে যেন আমি তার কাছে আত্মসমর্পণ করি, যদি আমি কাজ করার আগে ফিরে যাই।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ الرَّكْعَتَيْنِ قَبْلَ صَلَاةِ الصُّبْحِ فَلْيَضْطَجِعْ عَلَى جَنْبِهِ الْأَيْمَنِ ‏","","",""]];
